(window.GIM_TS=window.GIM_TS||{})["Zevachim.5"]={"from":120,"a":[["\u0003ולא על גבי מחילות.\u0004","אחרי שחשב שוב באותו נושא, מדוע הוסיפו עולי הגולה על המזבח, \u0003אמר רב יוסף: לאו היינו דתניא\u0004 \u0005[האם אין\u0006 זה מה \u0005ששנויה\u0006 בברייתא\u0005]\u0006 על עולי הגולה: \u0003\"ויכינו (את) המזבח על מכונתו\"\u0004 (עזרא ג, ג), לומר \u0003שהגיעו לסוף מדותיו\u0004 כלומר, עולי הגולה הגיעו למדות הנכונות של המזבח, יותר מאשר שלמה בבית ראשון? ומקשים: \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 בדברי דוד לשלמה: \u0003\"הכל בכתב מיד ה' עלי השכיל\u0004 כל מלאכות התבנית\" (דברי הימים א כח, יט), משמע שתבנית הבית הראשון היא מאת ה', ובודאי היתה נכונה וראויה!","\u0003אלא אמר רב יוסף:\u0004 המידות עצמן היו ראויות, ואולם משהגיעו למסקנה כי יש צורך להגדיל את שטח המזבח, \u0003קרא אשכח\u0004 \u0005[מקרא מצאו]\u0006 \u0003ודרש: \"ויאמר דויד זה הוא בית ה' האלהים וזה מזבח לעלה לישראל\"\u0004 (דברי הימים א כב, א), הרי שהוקש המזבח לבית \u0003כי\u0004 \u0005[כמו]\u0006 ה\u0003בית, מה בית\u0004 אורכו \u0003ששים אמה\u0004 (ראה מלכים א ו, ב), \u0003אף מזבח\u0004 אורכו יכול להיות עד \u0003ששים אמה.\u0004 ומעתה דנים באופן בו בנו את המזבח בבית שני.","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003בית\u0004 המקדש עצמו \u0003מינכרא\u0004 \u0005[ניכרת\u0006 היתה\u0005]\u0006 \u0003צורתו\u0004 לפי יסודותיו, וידעו היכן לחזור ולבנותו, \u0003אלא מזבח מנא ידעי\u0004 \u0005[מנין ידעו]?\u0006","\u0003אמר ר' אלעזר: ראו\u0004 בחזון \u0003מזבח בנוי ומיכאל השר הגדול עומד ומקריב עליו. ור' יצחק נפחא אמר: אפרו של יצחק ראו\u0004 בחזון \u0003שמונח באותו מקום\u0004 שצריך לבנות בו המזבח. \u0003ור' שמואל בר נחמני אמר: מכל הבית כולו הריחו ריח קטרת,\u0004 ואילו \u0003משם\u0004 ממקום המזבח \u0003הריחו ריח אברים.\u0004","\u0003אמר רבה בר בר חנה אמר ר' יוחנן: שלשה נביאים עלו עמהם מן הגולה, אחד שהעיד להם על המזבח\u0004 מה גודלו וצורתו. \u0003ואחד שהעיד להם על מקום המזבח\u0004 היכן הוא, \u0003ואחד שהעיד להם שמקריבין\u0004 קרבנות ציבור \u0003אף על פי שאין בית\u0004 בנוי, אלא מזבח בלבד.","\u0003במתניתא תנא\u0004 \u0005[בברייתא\u0006 שנויה\u0005]\u0006 מעין זה, \u0003ר' אליעזר בן יעקב אומר: שלשה נביאים עלו עמהן מן הגולה, אחד שהעיד להם על המזבח ועל מקום המזבח, ואחד שהעיד להם שמקריבין אף על פי שאין בית, ואחד שהעיד להם על התורה שתכתב\u0004 בכתב \u0003אשורית,\u0004 ולא בכתב העברי הקדום, שהיה מזמן משה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 הדברים האמורים במזבח: שתהא לו \u0003קרן\u0004 בראש כל אחת מפינותיו, \u0003וכבש\u0004 לעלות עליו, \u0003ויסוד, ו\u0004שיהא בנוי בצורת \u0003ריבוע\u0004 מדוייק — כל אלה \u0003מעכבין,\u0004 שאם חסר אחד מהם — אין זה מזבח. אבל \u0003מדת ארכו ומדת רחבו ומדת קומתו\u0004 — \u0003אין מעכבין.\u0004 ולגבי הפרטים המעכבים, שואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים האלה]?\u0006 \u0003אמר רב הונא,\u0004 משום ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 לגבי פרטים אלה: \u0003\"המזבח\",\u0004 ו\u0003כל מקום\u0004 שנאמר \"המזבח\" — \u0003לעכב,\u0004 שיש בכך הדגשה: רק באופן זה זהו המזבח.","ושואלים: \u0003אלא מעתה,\u0004 שזהו הכלל, \u0003כיור\u0004 (פיתוחים) שנעשו על המזבח \u0003ל\u0004דעת \u0003רבי, וסובב ל\u0004דעת \u0003ר' יוסי בר' יהודה, הכי נמי\u0004 \u0005[כך גם כן]\u0006 ש\u0003מעכב? דכתיב\u0004 \u0005[ש\u0006הרי \u0005נאמר]:\u0006 \u0003\"ונתתה אתה תחת כרכב המזבח מלמטה\"\u0004 (שמות כז, ה). \u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]:\u0006 \u0003איזהו כרכוב? רבי אומר: זה כיור. ר' יוסי בר' יהודה אומר: זה הסובב!\u0004","ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 אכן, הכרכוב מעכב. \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003אותו היום,\u0004 בו זרקו אתרוגים על כהן צדוקי שלא ניסך מים על המזבח בחג הסוכות (ראה סוכה מח,ב), \u0003נפגמה קרן מזבח, והביאו בול\u0004 (גוש) \u0003של מלח וסתמוהו, ולא מפני שכשר לעבודה\u0004 על ידי כך, \u0003אלא\u0004 כדי \u0003שלא יראה מזבח פגום.\u0004 ומדוע לא היה כשר? \u0003שכל מזבח שאין לו קרן וכבש ויסוד וריבוע\u0004 — \u0003פסול, ר' יוסי בר' יהודה אומר: אף הסובב\u0004 מעכב, משום שלדבריו זהו הכרכוב.","ועוד בענין הכרכוב, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003איזהו כרכוב? בין קרן לקרן\u0004 בראש המזבח, \u0003מקום הילוך רגלי הכהנים\u0004 ברוחב \u0003אמה.\u0004 ושואלים: \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003הכהנים בין קרן לקרן הוו אזלי\u0004 \u0005[היו הולכים]?\u0006 \u0003אלא אימא\u0004 \u0005[אמור]\u0006 ותקן כך: איזהו כרכוב — בין קרן לקרן, \u0003ו\u0004כן \u0003מקום הילוך רגלי הכהנים\u0004 הריהו ברוחב \u0003אמה.\u0004","ושואלים: \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"תחת כרכבו מלמטה עד חציו\"\u0004 (שמות לח, ד), משמע שהכרכוב אינו בראש המזבח, אלא בצידו! \u0003אמר רב נחמן בר יצחק: תרי הוו\u0004 \u0005[שני\u0006 כרכובים \u0005היו],\u0006 \u0003חד\u0004 \u0005[אחד]\u0006 \u0003לנוי,\u0004 שהוא מעין בליטה על קיר המזבח למעלה מחציו, \u0003וחד\u0004 \u0005[ואחד]\u0006 \u0003ל\u0004מקום הילוך \u0003כהנים\u0004 בראש המזבח, שעושים בליטה סביב למקום ההילוך, כדי ש\u0003לא נשתרקו\u0004 \u0005[יחליקו]\u0006 הכהנים.","שנינו בברייתא: \u0003מדת ארכו ומדת רחבו ומדת קומתו אין מעכבין. אמר ר' מני: ובלבד שלא יפחתנו ממזבח שעשה משה.\u0004 ושאלו: \u0003וכמה\u0004 הוא השיעור של אורכו ורוחבו? \u0003אמר רב יוסף:\u0004 שיעורו \u0003אמה. מחכו עליה\u0004 \u0005[היו צוחקים עליו],\u0006 שהרי כתוב מפורש הוא: \u0003\"חמש אמות ארך וחמש אמות רחב רבוע יהיה המזבח\"\u0004 (שמות כז, א)!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: דלמא\u0004 \u0005[שמא]\u0006 \u0003מקום מערכה\u0004 של העצים \u0003קאמר מר\u0004 \u0005[אמר אדוני],\u0006 שרוחב קרנות המזבח היה אמה בכל צד, ועוד אמה מכל צד להילוך הכהנים. ונמצא שנותרה אמה על אמה לצורך המערכה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף בהערכה: \u0003מר דגברא רבה\u0004 \u0005[אדוני שאדם גדול]\u0006 \u0003הוא, ידע מאי קאמינא\u0004 \u0005[יודע מה שאמרתי]\u0006 ולמה התכוונתי. \u0003קרי עלייהו\u0004 \u0005[וקרא עליהם]\u0006 על אלה שלגלגו עליו:"],["\u0003\"בני קטורה\",\u0004 לומר שכשם שבני קטורה היו אמנם בני אברהם אבל אינם כיצחק ויעקב, כך הם, תלמידיו הם, אבל אינם כאביי. אגב שהוזכר ביטוי זה מסופר, \u0003בני אחתיה\u0004 \u0005[אחותו]\u0006 של \u0003ר' טרפון הוו יתבי קמיה\u0004 \u0005[היו יושבים לפני]\u0006 \u0003ר' טרפון,\u0004 ולא אמרו דבר. \u0003פתח ואמר,\u0004 על מנת לעודדם לומר דבר כלשהו: \u0003\"ויוסף אברהם ויקח אשה ושמה יוחני\",\u0004 \u0003אמרי ליה\u0004 \u0005[אמרו לו]:\u0006 \u0003\"קטורה\" כתיב\u0004 \u0005[נאמר]!\u0006 \u0003קרי\u0004 \u0005[\u0006היה \u0005קורא]\u0006 \u0003עליהם\u0004 בלגלוג: \u0003בני קטורה,\u0004 שרק דבר זה ידעו לומר.","\u0003אמר אביי בר הונא אמר רב חמא בר גוריא: גזירין שעשה משה\u0004 לקיים את המצוה של שריפת עצים על המזבח, \u0003אורכן אמה ורוחבן אמה, ועוביין\u0004 היה \u0003כמחק\u0004 מעין מקל שטוח שמשתמשים בו למחוק \u0003גודש\u0004 של מידת \u0003סאה.\u0004","\u0003אמר ר' ירמיה:\u0004 האורך והרוחב של הגזירים נמדדו \u0003באמה גדומה\u0004 (חסירה) פחות ממידת אמה. \u0003אמר רב יוסף, ולאו היינו דתניא\u0004 \u0005[והאם אין זה\u0006 מה \u0005ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003\"על העצים אשר על האש אשר\u0004 \u0003על המזבח\"\u0004 (ויקרא א, ח), לומר \u0003שלא יהו עצים יוצאין מן\u0004 \u0003המזבח כלום?\u0004 והואיל ומקום המערכה של מזבח משה היה אמה על אמה, נמצא שכן היתה מידתם.","\u0003תנן התם\u0004 \u0005[שנינו שם]\u0006 במסכת מדות: \u0003כבש היה לדרומה של מזבח, אורך\u0004 \u0003שלשים ושתים\u0004 אמה \u0003על רוחב שש עשרה.\u0004 ושואלים: \u0003מנא הני\u0004 \u0003מילי\u0004 \u0005[מנין הדברים הללו]\u0006 שהכבש הוא בדרום? \u0003אמר רב הונא,\u0004 \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ושחט אותו על ירך המזבח צפונה\"\u0004 (ויקרא א, יא), \u0003שיהא ירך\u0004 המזבח, כלומר רגלו, קצהו, \u0003בצפון,\u0004 וממילא נמצאים \u0003פניו\u0004 החלק הקדמי, דרכו עולים למזבח \u0003בדרום.\u0004","ושואלים, \u0003אימא\u0004 \u0005[אמור]:\u0006 גם \u0003ירך בצפון ו\u0004גם \u0003פניו בצפון!\u0004 \u0003אמר רבא: רמי גברא אאפיה\u0004 \u0005[מוטל איש על פניו]\u0006 כלומר, הדימוי של המזבח (פנים וירך) הוא כאדם שוכב, שראשו בצד דרום ורגלו בצד צפון. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אדרבה, תריץ ואותיב גברא\u0004 \u0005[יישר,\u0006 הקם \u0005והושב\u0006 את \u0005האיש],\u0006 שאתה יכול \u0005לומר שהיה המזבח נראה כאדם היושב, שפניו ורגליו הם באותו כיוון!\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003\"רבוע\" כתיב\u0004 \u0005[נאמר],\u0006 וכוונתו כעין רביצה, שכיבה, שהאותיות ע' וצ' מתחלפות. הקשה לו: \u0003והא מיבעי ליה\u0004 \u0003דמרבע רבועי\u0004 \u0005[והרי צריך לו\u0006 להיכתב \"רבוע\" ללמד \u0005שיהיה מרובע]!\u0006 השיב לו רבא: \u0003מי כתיב\u0004 \u0005[האם נאמר]\u0006 \u0003\"מרובע\"?\u0004 הקשה לו אביי: להיפך, \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005],\u0006 שהכוונה היא לרובץ, \u0003מי כתיב\u0004 \u0005[האם נאמר]\u0006 \u0003\"רבוץ\"? אמר ליה\u0004 \u0005[לו]:\u0006 לכן \u0003\"רבוע\" כתיב\u0004 \u0005[נאמר],\u0006 \u0003דמשמע הכי ומשמע הכי\u0004 \u0005[שמשמעו כך ומשמעו כך],\u0006 גם כרבוץ וגם מרובע.","ומוסיפים: \u0003ו\u0004ה\u0003תנא מייתי לה מהכא\u0004 \u0005[ומביא\u0006 לומד \u0005את\u0006 הדברים האלה \u0005מכאן],\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יהודה\u0004 \u0003אומר:\u0004 נאמר לגבי המזבח \u0003\"ומעלתהו פנות קדים\"\u0004 (יחזקאל מג, יז), ללמד \u0003כי\u0004 \u0003כל פינות\u0004 (פניות) \u0003שאתה פונה\u0004 כשאתה עולה על המזבח \u0003לא יהו אלא דרך ימין למזרח\u0004 (\"קדים\"), ורק אם הכבש בדרום פונה הכהן משם ימינה לצד מזרח.","ושואלים: והרי בכתוב זה נזכרה רק פניה למזרח (\"פנות קדים\") אבל לא פניה לימין, \u0003ואימא\u0004 \u0005[ואמור]:\u0006 נעשה את הכבש בצפון, ויפנה ל\u0003שמאל למזרח!\u0004 ומשיבים: \u0003לא סלקא דעתך\u0004 \u0005[יעלה על דעתך]\u0006 שיפנה לשמאל, \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003רמי בר (יחזקיה): ים\u0004 (הכיור הגדול) \u0003שעשה שלמה\u0004 נאמר בו: \u0003\"עמד על שנים עשר (עמודים) בקר שלשה פנים צפונה\u0004 \u0003ושלשה פנים ימה ושלשה פנים נגבה ושלשה פנים מזרחה\"\u0004 (דברי הימים ב ד, ד), ומן התיאור הזה: צפון, מערב, דרום, מזרח, יש ללמוד \u0003ש\u0004\u0003כל פינות שאתה פונה לא יהו אלא\u0004 \u0003דרך ימין,\u0004 וכפי שהוכחנו מן הכתוב \"ומעלותיה פנות קדים\" הכוונה היא שפונה \u0003למזרח.\u0004","ומקשים: \u0003ההוא מיבעי ליה לגופיה\u0004 \u0005[אותו\u0006 כתוב, בענין הים שעשה שלמה, \u0005נצרך לו לגופו]\u0006 ללמד כמה עמודים היו וכיצד עמדו! ומשיבים: \u0003אם כן,\u0004 החזרה על \u0003\"פנים\" \"פנים\"\u0004 \u0003למה לי?\u0004 ללמד מכאן שכך היא הדרך שצריך לפנות בה.","\u0003שאל ר' שמעון בן יוסי בן לקוניא את ר' יוסי, אומר\u0004 \u0003היה ר' שמעון בן יוחי: אויר\u0004 (חלל מסויים) \u0003יש בין כבש\u0004 \u0003למזבח? אמר לו: ואתה אי\u0004 (אין) \u0003אתה אומר כן\u0004 שיש חלל? \u0003והלא\u0004 \u0003כבר נאמר: \"ועשית עלתיך הבשר והדם\"\u0004 (דברים יב, כז), וההשוואה הזו מלמדת: \u0003מה דם\u0004 ניתן \u0003בזריקה\u0004 כשהכהן עומד בצד המזבח (ראה ויקרא א, ה) ולא עליו, \u0003אף בשר\u0004 העולה מוקרב \u0003בזריקה,\u0004 והואיל ואין הכהן יכול לעמוד על רצפת העזרה ומשם לזרוק את האיברים למערכה, וצריך לעלות על הכבש לשם כך — צריך שיהא הכבש מופרד מן המזבח.","\u0003אמר לו:\u0004 אם כדי לזרוק את הבשר — אין צורך שיהא הכבש נפרד מן המזבח, \u0003שאני אומר:\u0004 אפשר שיהא הכהן \u0003עומד\u0004 על המזבח עצמו, \u0003בצד מערכה\u0004 עליה נשרפים חלקי הקרבן, \u0003וזורק.\u0004","\u0003אמר לו:\u0004 \u0003כשהוא זורק\u0004 את הבשר, \u0003האם\u0004 \u0003למערכה\u0004 ה\u0003דלוקה הוא זורק\u0004 לעצים הבוערים בלב המערכה, \u0003או למערכה שאינה\u0004 \u0003דלוקה הוא זורק? הוי אומר: למערכה דלוקה הוא זורק,\u0004 ולא בסמוך אליו. ואם כן אין צורך להקיש בשר לדם כדי ללמד דבר זה, כי \u0003התם\u0004 \u0005[שם]\u0006 אינו זורק אלא \u0003משום\u0004 ש\u0003לא אפשר\u0004 אחרת! אלא ודאי בא ההיקש, שהוא מיותר לכאורה, ללמדנו שצריך שיהא הפסק בין הכהן העומד על הכבש לבין המזבח.","\u0003רב פפא אמר:\u0004 כך צריך להבין היקש זה של בשר לדם: \u0003כי\u0004 \u0005[כמו]\u0006 \u0003דם, מה דם אויר קרקע מפסיקו, אף בשר\u0004 \u0003אויר קרקע מפסיקו.\u0004","\u0003אמר רב יהודה: שני כבשים קטנים יוצאין\u0004 \u0003מן הכבש\u0004 הגדול, \u0003שבהן פונים\u0004 הכהנים \u0003ליסוד ולסובב, ומובדלין מן המזבח מלא נימא\u0004 (חוט), \u0003משום שנאמר\u0004 לגבי המזבח: \u0003\"סביב\"\u0004 (ויקרא א, ה) כלומר, שאפשר יהיה לסובב את המזבח מכל צד, ואינו מחובר לדבר אחר. \u0003ור' אבהו אמר\u0004 טעם אחר: נאמר במזבח \u0003\"רבוע\"\u0004 (שמות כז, א), ואם היו הכבשים מחוברים אליו, שוב לא היתה צורתו צורת רבוע.","ומעירים: \u0003ואיצטריך למכתב\u0004 \u0005[וצריך היה לכתוב]\u0006 \u0003\"סביב\" ואיצטריך למכתב\u0004 \u0005[וצריך היה לכתוב]\u0006 \u0003\"רבוע\", דאי כתב\u0004 \u0003רחמנא\u0004 \u0005[שאם היתה כותבת התורה]\u0006 רק \u0003\"סביב\", הוה אמינא\u0004 \u0003דעגיל מעגל\u0004 \u0005[הייתי אומר ש\u0006הוא \u0005מעוגל],\u0006 \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"רבוע\". ואי כתב רחמנא\u0004 \u0005[ואם היתה כותבת התורה]\u0006 רק \u0003\"רבוע\", הוה אמינא דאריך וקטין\u0004 \u0005[הייתי אומר ש\u0006הוא \u0005ארוך וצר],\u0006 \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"סביב\",\u0004 שיהיה אורכו ורחבו שווים מכל הצדדים.","\u0003תנן התם\u0004 \u0005[שנינו שם]\u0006 במסכת מדות, בתיאור רוחב העזרה מצפון לדרום: \u0003הכבש והמזבח ששים ושתים\u0004 אמה הם. ותוהים: \u0003הני\u0004 \u0005[אלה]\u0006 ששים ושתים? הלוא \u0003שיתין\u0004 \u0005[ששים]\u0006 \u0003וארבעה\u0004 אמות \u0003הוו\u0004 \u0005[הם],\u0006 שהרי המזבח הוא שלושים ושתים אמות, וכך אורך הכבש, כפי ששנינו במשנה אחרת שם! ומשיבים: הרי זה כפי ששנינו בברייתא: \u0003נמצא\u0004 הכבש \u0003פורח\u0004 מצוי באויר באורך \u0003אמה על יסוד ו\u0004באורך \u0003אמה על סובב,\u0004 שהכבש נמשך ועולה על האמות האלה, ולכן כאשר מודדים את אורך הכבש והמזבח ביחד, כמה תופסים הם בשטח העזרה — אין זה אלא ששים ושתים אמה."],["\u0003אמר רמי בר חמא: כל כבשי כבשים\u0004 כלומר, הכבשים הקטנים, השיפוע שלהם הוא \u0003שלש אמות\u0004 של אורך \u0003לאמה\u0004 גובה, \u0003חוץ מכבשו של מזבח, שהיה שלש אמות ומחצה ואצבע ושליש אצבע בזכרותא\u0004 \u0005[בקצה]\u0006 לכל אמה גובה, שעשו את השיפוע מתון יותר, כדי להקל על הכהנים בנשיאת איברי העולה, ומחשש החלקה.","\u0003מנחות היו נקמצות\u0004 כלומר, הכהן נוטל קומץ מן המנחה כדי להקטירו על המזבח, \u0003בכל מקום בעזרה\u0004 (ולא רק בצפון), \u0003ונאכלות לפנים מן הקלעים\u0004 של העזרה, \u0003לזכרי כהונה\u0004 לכהנים זכרים, \u0003בכל מאכל\u0004 צלי או מבושל, \u0003ליום ולילה עד חצות.\u0004","\u0003אמר ר' אלעזר: מנחה שנקמצה בהיכל\u0004 עצמו — \u0003כשירה, שכן מצינו\u0004 מעין קמיצה בהיכל \u0003בסילוק בזיכין,\u0004 שהיו שני בזיכי לבונה מונחים ליד לחם הפנים בהיכל, ובשבת לוקחים (מסלקים) אותם משם כדי להקטירם ובכך להתיר את לחם הפנים באכילה לכהנים. וסילוק הבזיכים הוא, איפוא, כמו קמיצה ללחם הפנים.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003ר' ירמיה\u0004 ממה ששנינו בברייתא: מה שנאמר לגבי המנחה \"והביאה אל בני אהרן הכהנים וקמץ משם\" (ויקרא ב, ב), \u0003\"וקמץ משם\",\u0004 כוונתו — \u0003ממקום שרגלי הזר\u0004 שהביאה \u0003עומדות.\u0004","\u0003בן בתירא\u0004 דורש באופן אחר, ו\u0003אומר: מנין שאם קמץ בשמאל שיחזיר\u0004 את הקומץ לכלי, ויחזור \u0003ויקמוץ בימין? תלמוד לומר:\u0004 \"וקמץ \u0003משם\", ממקום שקמץ כבר.\u0004 על כל פנים, לדברי התנא הראשון כיצד ניתן לקמוץ בהיכל? והרי זר אינו יכול להיכנס לשם!","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003הוא מותיב לה\u0004 \u0005[היה מקשה את הקושיה הזו]\u0006 \u0003והוא מפרק לה\u0004 \u0005[היה מתרץ אותה],\u0006 \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' עקיבא לר' ירמיה בר תחליפא, אסברא\u0004 \u0005[אסביר]\u0006 \u0003לך: לא נצרכא\u0004 דרשה זו כדי להגביל את מקום הקמיצה, \u0003אלא\u0004 להיפך, \u0003להכשיר\u0004 את \u0003כל העזרה כולה\u0004 לקמיצה, גם במקום שהותר לזר להיכנס. ומדוע צריך לכך?","כי \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל ועולה קדשי קדשים ו\u0004גם \u0003מנחה\u0004 היא \u0003קדשי קדשים,\u0004 יש לומר: \u0003מה עולה טעונה\u0004 דווקא \u0003צפון\u0004 לשחיטתה, \u0003אף מנחה טעונה צפון\u0004 לקמיצתה.","ומשיבים: לא ניתן היה לומר כך, כי יש לדחות: \u0003מה לעולה\u0004 שהיא חמורה יותר, \u0003שכן\u0004 היא עולה \u0003כליל!\u0004","ואם תאמר שהיה מקום ללמוד \u0003מחטאת\u0004 שגם היא קדשי קדשים ושחיטתה בצפון ואינה עולה כליל — גם זאת יש לפרוך: \u0003מה לחטאת\u0004 שהיא חמורה, \u0003שכן מכפרת על חייבי כריתות!\u0004","ואם תאמר: נלמד \u0003מאשם,\u0004 שהוא קדשי קדשים ושחיטתו בצפון — יש לדחות: \u0003מה לאשם, שכן מיני דמים,\u0004 ואין ללמוד מכאן למנחה.","ומוסיפים: \u0003מכולהו\u0004 \u0005[מכולם]\u0006 ביחד גם כן אי אפשר היה ללמוד, מן הצד השווה שבהם, שהם קדשי קדשים, וכן המנחות, משום ש\u0003מה לכולהו\u0004 \u0005[לכולם]\u0006 \u0003שכן מיני דמים\u0004 הם!","\u0003אלא איצטריך\u0004 \u0005[הוצרך הדבר]\u0006 להיאמר מפני טעם אחר, \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל וכתיב\u0004 \u0005[ונאמר]\u0006 במנחה תחילה: \u0003\"והגישה\u0004 (הכהן) \u0003אל המזבח\"\u0004 (ויקרא ב, ח), ונאמר בקמיצה: \u0003\"והרים ממנו בקמצו\"\u0004 (ויקרא ו, ח), ו\"ממנו\" כוונתו מן הכלי בו הגיש את המנחה תחילה אל המזבח, יש לומר:","\u0003מה הגשה בקרן מערבית דרומית, אף קמיצה\u0004 מכלי זה תהיה רק \u0003בקרן מערבית דרומית, קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שהותרה קמיצה גם במקומות אחרים בעזרה.","ובאותו ענין \u0003אמר ר' יוחנן: שלמים\u0004 שמקום שחיטתם בכל העזרה, \u0003ששחטן בהיכל\u0004 — \u0003כשרים, שנאמר: \"ושחטו (אותו) פתח אהל מועד\"\u0004 (ויקרא ג, ב), \u0003ולא יהא טפל חמור מן העיקר,\u0004 שאם פתח ההיכל ראוי לשחיטת השלמים, כל שכן ההיכל עצמו.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על סברה זו ממה ששנינו, \u0003ר' יוחנן בן בתירה אומר: מנין שאם הקיפו גוים את כל העזרה,\u0004 והיו יורים עליה, עד שאין הכהנים יכולים לשהות שם, \u0003שהכהנים נכנסין לשם\u0004 (להיכל) \u0003ואוכלין שם קדשי קדשים? תלמוד לומר: \"בקדש הקדשים תאכלנו\"\u0004 (במדבר יח, י).","\u0003ואמאי\u0004 \u0005[ומדוע]\u0006 צריך הוא ללימוד זה? \u0003נימא\u0004 \u0005[נאמר]\u0006 כך, כדרך שנימק זאת ר' יוחנן: הרי נאמר \u0003\"בחצר אהל מועד יאכלוה\"\u0004 (ויקרא ו, ט), \u0003ולא יהא טפל חמור מן העיקר,\u0004 שאם החצר ראויה לאכילת קדשי קדשים, כל שכן אהל מועד עצמו!","ודוחים: \u0003הכי השתא\u0004 \u0005[כך אתה משוה]?!\u0006 \u0003התם\u0004 \u0005[שם]\u0006 לגבי שחיטה, שמדובר בענין \u0003עבודה,\u0004 ו\u0003אדם עובד\u0004 ומשרת את רבו (אדונו) \u0003במקום\u0004 בו \u0003רבו\u0004 נמצא — \u0003אמרינן\u0004 \u0005[אומרים אנו]\u0006 \u0003לא יהא טפל חמור מן העיקר.\u0004 ואילו לענין \u0003אכילה,\u0004 ש\u0003אין אדם אוכל במקום רבו,\u0004 שאין זו דרך ארץ, \u0003לא יהא טפל חמור מן העיקר לא אמרינן\u0004 \u0005[אין אנו אומרים],\u0006 ולכן צריך כתוב מיוחד שמלמדנו שמותר לעשות זאת.","\u0003חטאת העוף היתה נעשית על קרן דרומית מערבית\u0004 של המזבח. \u0003ובכל מקום היתה כשירה, אלא זה היתה מקומה\u0004 שקבעו לה. \u0003ושלשה דברים היתה אותה קרן משמשת מלמטה\u0004 (בחצי המזבח התחתון, למטה מחוט הסיקרא), \u0003ושלשה מלמעלה. מלמטה:\u0004 מעשה \u0003חטאת העוף, והגשות\u0004 של המנחות בכלי לפני הקמיצה, \u0003ושירי הדם\u0004 ששופכים שם.","\u0003ומלמעלן\u0004 היתה משמשת ל\u0003ניסוך היין\u0004 שמביאים עם הקרבנות, או כקרבן בפני עצמו, \u0003ו\u0004לניסוך \u0003המים\u0004 בחג הסוכות, שבקרן שבראשה היו נקבים המיועדים לכך. \u0003ו\u0004כן היתה משמשת לעשיית \u0003עולת העוף כשהיא רבה במזרח\u0004 (בקרן דרומית מזרחית, ששם היתה נעשית) שאם היו עולות מרובות, ולא היה שם מקום ליותר מכהן אחד, היו עושים אותה בקרן הדרומית מערבית, כאשר יבואר בגמרא.","כלל אמרו: \u0003כל העולין למזבח\u0004 — \u0003עולין\u0004 בכבש \u0003דרך ימין\u0004 לכיוון קרן מזרחית דרומית,"],["\u0003ומקיפין\u0004 את המזבח עד לקרן המערבית דרומית, \u0003ויורדין דרך שמאל, חוץ מן העולה לשלשה אלו,\u0004 שהיו נעשים בראש קרן דרומית מערבית: ניסוך היין, ניסוך המים, ועולת העוף כשהיא מרובה במזרח, \u0003שהיו עולין\u0004 ישר לקרן זו, מן הכבש שבדרום לצד שמאל, \u0003ו\u0004כשגומרים עבודתם \u0003יורדין על העקב\u0004 כלומר, חוזרים בדרך שבה באו.","שואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]\u0006 שמקום החטאת הוא בקרן דרומית מערבית? \u0003אמר ר' יהושע, אמר קרא\u0004 \u0005[הכתוב]\u0006 לגבי מנחת חוטא, הבאה במקום חטאת הבהמה והעוף, \u0003\"לא ישים עליה שמן ולא יתן עליה לבנה כי חטאת היא\"\u0004 (ויקרא ה, יא), ומפסוק זה רואים ש\u0003חטאת קרויה מנחה, ומנחה קרויה חטאת,\u0004 ולפיכך יש ללמוד מזו על זו:","\u0003מה חטאת טעונה\u0004 שחיטה ב\u0003צפון\u0004 — \u0003אף מנחה טעונה\u0004 קידוש הקומץ בכלי ב\u0003צפון. ומה מנחה\u0004 מגישה \u0003בקרן מערבית דרומית, אף חטאת\u0004 מזה דמה \u0003בקרן\u0004 \u0003מערבית דרומית.\u0004","ושואלים: \u0003ומנחה\u0004 \u0003גופה מנלן\u0004 \u0005[עצמה מנין לנו]\u0006 שמגישים אותה שם? \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 על הפסוק: \"וזאת תורת המנחה הקרב אותה... לפני ה' אל פני המזבח\" (ויקרא ו, ז). ממה שנאמר \u0003\"לפני ה'\"\u0004 (ויקרא ו, ז), \u0003יכול\u0004 שיגיש אותה \u0003במערב\u0004 שהוא לפני ה', מול ההיכל? \u0003תלמוד לומר: \"אל פני המזבח\"\u0004 (ויקרא ו, ז) בדרום, שמשם עולים אליו.","ומצד שני, \u0003אי\u0004 \u0005[אם]\u0006 נאמר \u0003\"אל פני המזבח\", יכול\u0004 יגישה \u0003בדרום,\u0004 שהוא פני המזבח, שמשם עולים אליו? \u0003תלמוד לומר: \"לפני ה'\",\u0004 במערב. \u0003הא\u0004 \u0005[הרי]\u0006 \u0003כיצד\u0004 מקיימים את שני הכתובים? \u0003מגישה בקרן מערבית דרומית כנגד חודה של קרן,\u0004 והרי זה גם בדרום וגם במערב, \u0003ודיו.\u0004","\u0003ר' אליעזר אומר: יכול יגישנה למערבה של קרן או לדרומה של קרן\u0004 לאיזו שירצה? \u0003אמרת: כל מקום שאתה מוצא שני מקראות, אחד מקיים\u0004 מה שנאמר בו \u0003עצמו ומקיים\u0004 גם מה שנאמר ב\u0003חבירו, ואחד מקיים עצמו ומבטל חבירו\u0004 — \u0003מניחין זה שמקיים עצמו ומבטל חבירו, ותופשין את שמקיים עצמו ומקיים חבירו.\u0004","ולפיכך, בענייננו, \u0003כשאתה אומר \"אל פני ה'\"\u0004והוא \u0003במערב, היכן קיימת \"אל פני המזבח\"?\u0004 אבל \u0003כשאתה אומר \"אל פני המזבח\"\u0004 והוא \u0003בדרום, קיימת \"לפני ה'\",\u0004 במערב.","ותוהים: \u0003בדרום היכן קיימת\u0004 \"לפני ה'\"? \u0003אמר רב אשי, קסבר האי תנא\u0004 \u0005[סבור תנא זה]:\u0006 \u0003כוליה\u0004 \u0005[כל]\u0006 ה\u0003מזבח בצפון\u0004 העזרה \u0003קאי\u0004 \u0005[\u0006הוא \u0005עומד],\u0006 מן האמצע וצפונה, ולכן קצהו הדרומי מצוי מול פתח ההיכל, שנמצא באמצע \u0005העזרה, והוא ממש \"לפני ה'\".\u0006","שנינו במשנה לגבי חטאת העוף: \u0003בכל מקום היתה כשירה,\u0004 אלא זה היה מקומה (בקרן דרומית מערבית). ושואלים: \u0003מאי קאמר\u0004 \u0005[מה הוא אומר]?\u0006 מה פירוש התוספת \"אלא זה היה מקומה\"? שהרי כבר אמרנו תחילה במשנה שהיא נעשית בקרן דרומית מערבית דווקא! \u0003אמר רב אשי, הכי קאמר\u0004 \u0005[כך הוא אומר]:\u0006 \u0003בכל מקום היתה כשירה למליקתה, אלא זה,\u0004 קרן דרומית מערבית, \u0003היה מקומה להזאתה.\u0004","ומעירים: \u0003תנינא להא דתנו רבנן\u0004 \u0005[שנינו\u0006 איפוא במשנה \u0005את מה ששנו חכמים\u0006 בברייתא\u0005]\u0006 לגבי חטאת העוף: \u0003מלקה בכל מקום במזבח\u0004 — \u0003כשירה, היזה דמה בכל מקום\u0004 במזבח — \u0003כשירה, היזה\u0004 את הדם \u0003ולא מיצה\u0004 את הנותר על קיר המזבח, כפי שנאמר בתורה \"והזה מדם החטאת על קיר המזבח והנשאר בדם יימצה אל יסוד המזבח\" (ויקרא ה, ט) — עדיין \u0003כשירה, ובלבד שיתן מחוט הסיקרא ולמטה מדם הנפש\u0004 (הדם שהנפש יוצאה בו).","ושואלים: \u0003מאי קאמר\u0004 \u0005[מה הוא אומר]\u0006 \"מלבד שיתן מחוט הסיקרא ולמטה\"? והרי נאמר תחילה שאם היזה בכל מקום כשירה! ומסבירים: \u0003הכי קאמר\u0004 \u0005[כך הוא אומר]:\u0006 \u0003מלקה בכל מקום במזבח\u0004 — \u0003כשירה, מיצה דמה בכל מקום במזבח\u0004 — \u0003כשירה,\u0004"],["\u0003ש\u0004כן \u0003אם היזה ולא מיצה\u0004 — גם כן \u0003כשירה, ובלבד שיתן\u0004 בהזאה \u0003מחוט הסיקרא ולמטה מדם הנפש.\u0004","שנינו במשנה כי \u0003שלשה דברים\u0004 היו עושים בקרן דרומית מערבית למטה: חטאת העוף וההגשות ושיירי הדם. ומבררים: \u0003חטאת העוף\u0004 — \u0003הא דאמרן\u0004 \u0005[זו שאמרנו]\u0006 במשנה (דף סג,ב) שהיא נעשית שם.","\u0003הגשות\u0004 של המנחה — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והגישה אל פני המזבח\"\u0004 (ראה ויקרא ב, ח). \u0003שירי הדם\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ואת כל דם הפר ישפך אל יסוד המזבח\"\u0004 (ויקרא ד, ז).","ועוד שנינו כי שלושה דברים נעשו בקרן דרומית מערבית \u0003מלמעלה: ניסוך המים והיין, ועולת העוף כשהיא רבה במזרח.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 היו עושים את העולה לכתחילה בקרן דרומית מזרחית? \u0003ר' יוחנן אמר: מפני שקרובה מ\u0004שאר הקרנות ל\u0003בית הדשן\u0004 (המקום בו מניחים את הדשן שמרימים מן המזבח בכל בוקר), ושם משליכים את המוראה והנוצות של עולת העוף.","ולגבי מה ששנינו שניתן לעשותה בקרן דרומית מערבית, \u0003אמר ר' יוחנן: בא וראה כמה גדול כחן של כהנים, שאין לך\u0004 חלק \u0003קל בעופות יותר ממוראה\u0004 (זפק) \u0003ונוצה, פעמים שהכהן זורקן יותר מבשלשים אמה\u0004 כשהוא עושה את עולת העוף בקרן דרומית מערבית, כשהיא רבה במזרח.","\u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]\u0006 לגבי סדר עבודת התמיד שבמקדש: \u0003נטל\u0004 הכהן \u0003מחתה של כסף ועלה לראש המזבח,\u0004 אל מקום המערכה \u0003ופינה את הגחלים אילך ואילך וחתה\u0004 (נטל במחתה) \u0003מן\u0004 הגחלים \u0003המאוכלות הפנימיות ויורד.\u0004 כשירד מן הכבש ו\u0003הגיע לרצפה מחזיר פניו\u0004 שמאלה \u0003כלפי צפון והולך למזרחו של כבש כעשר אמות,\u0004 ושם \u0003צבר את הגחלים על גבי הרצפה, רחוק מן הכבש שלשה טפחים, מקום שנותנין מוראה ונוצה ודישון מזבח הפנימי והמנורה.\u0004 ומקום זה היה מרוחק יותר משלושים אמה מקרן מערבית דרומית.","ושואלים: עד לשם \u0003הני טפי מתלתין וחד הויין\u0004 \u0005[אלה יותר משלשים ואחת\u0006 אמה \u0005הן]!\u0006 ומשיבים: \u0003מקום גברי לא חשיב\u0004 \u0005[מקום האנשים,\u0006 מקומו של הכהן עצמו, \u0005אינו מונה]\u0006 ולכן יש להחסיר מחשבון זה אמה, שהיא מקום עמידתו של הכהן.","שנינו במשנה: \u0003כל העולים למזבח\u0004 היו עולים דרך ימין ומקיפים את המזבח ויורדים דרך שמאל, חוץ מהעולים לשלושה דברים אלה: ניסוך היין, וניסוך המים, ועולת העוף כשהיא רבה במזרח, שהיו פונים מיד לשמאלם. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 שאלו לא היו מקיפים דרך ימין? \u0003אמר ר' יוחנן: נסכים\u0004 — \u0003שמא יתעשנו\u0004 בעשן העולה מן המזבח בתוך כדי ההילוך סביב למזבח כולו. \u0003ועולת העוף\u0004 — \u0003שמא תמות בעשן.\u0004","\u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו: כשהכהן הגדול עושה את עבודת התמיד בעצמו, ולאחר שסידר את איברי התמיד על המערכה, \u0003בא לו להקיף את המזבח, מאין הוא מתחיל? מקרן דרומית מזרחית, מזרחית צפונית, צפונית מערבית, מערבית דרומית, ונותנין לו יין לנסך.\u0004 הרי שאין חוששים שיתעשן היין!","\u0003אמר ר' יוחנן:\u0004"],["אין מדובר אלא על \u0003הקפה ברגל\u0004 בלא שיהא היין בידו, וכשמגיע לקרן מערבית דרומית נותנים לו את היין. \u0003אמר רבא: דיקא נמי\u0004 \u0005[מדוייק גם כן],\u0006 \u0003דקתני\u0004 \u0005[ששנה]:\u0006 \u0003נותנין לו יין לנסך, ולא קתני\u0004 \u0005[שנה]:\u0006 \u0003אומר לו \"נסך\", שמע מינה\u0004 \u0005[למד מכאן]\u0006 שעד אותה שעה אינו מחזיק את היין בידו.","ובענין ששנינו במשנתנו \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 \u0003: כל העולין למזבח עולין דרך ימין\u0004 הכבש \u0003ויורדין דרך שמאל\u0004 של הכבש, \u0003עולין דרך מזרח ויורדין דרך מערב, חוץ מן העולה לשלשה דברים הללו\u0004 ניסוך היין והמים ועולת העוף, הנעשים בקרן דרומית מערבית, \u0003שעולים דרך מערב ויורדין דרך מערב, עולין דרך ימין ויורדין דרך ימין.\u0004","ותוהים: וכי העולים דרך מערב עולים \u0003דרך ימין?\u0004 הלא כאשר עולה בכבש מדרום, דרך מערב \u0003דרך שמאל הוא! אמר רבינא, תני\u0004 \u0005[שנה]\u0006 ותקן: \u0003שמאל. רבא אמר: מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003ימין? ימין\u0004 של \u0003מזבח\u0004 שחזיתו של המזבח פונה לדרום, ולפיכך צד מערב הריהו ימין שלו. \u0003ו\u0004לפי זה \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003שמאל\u0004 ששנינו בתחילת הברייתא, שהיורד מן המזבח יורד דרך שמאל? \u0003שמאל דגברא\u0004 \u0005[של האיש]\u0006 העומד מול המזבח.","ומקשים: \u0003וניתני\u0004 \u0005[ונשנה]\u0006 \u0003או אידי ואידי\u0004 \u0005[זה וזה],\u0006 בתחילת הברייתא ובסופה, לפי פניו של ה\u0003מזבח, או אידי ואידי דגברא\u0004 \u0005[זה וזה,\u0006 לפי כיוון עלייתו \u0005של האיש]!\u0006 וכיצד משתמש בשני מובנים שונים באותה ברייתא? ואומרים: אכן, \u0003קשיא\u0004 \u0005[קשה].\u0006","\u0003חטאת העוף כיצד היה נעשית? (עלה לכבש ופנה לסובב בא לו לקרן דרומית מזרחית). היה מולק\u0004 חותך בציפורן אגודלו \u0003את ראשה ממול ערפה\u0004 כלומר, מאחורי צווארה, \u0003ואינו מבדיל\u0004 (מפריד) את הראש מן הגוף, \u0003ו\u0004כשהוא אוחז \u0003מזה מדמה על קיר המזבח. שירי הדם היה מתמצה על היסוד. ואין למזבח אלא דמה, וכולה\u0004 נאכלת \u0003לכהנים.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003\"והזה מדם החטאת\u0004 על קיר המזבח\" (ויקרא ה, ט) — \u0003מגוף החטאת\u0004 כלומר, לא מתוך כלי, ולא באצבע, אלא מגוף העוף עצמו. \u0003הא\u0004 \u0005[הרי]\u0006 \u0003כיצד? אוחז בראש ובגוף\u0004 של העוף \u0003ומזה\u0004 מן הדם \u0003על קיר המזבח.\u0004 והוצרך לומר \"קיר המזבח\", להדגיש: \u0003ולא על קיר הכבש ולא על קיר היכל ולא על קיר אולם. ואיזה\u0004 קיר של המזבח? \u0003זה קיר התחתון\u0004 של המזבח, מחוט הסיקרא ולמטה.","ושואלים: \u0003או אינו אלא קיר העליון? ו\u0004לכאורה \u0003דין\u0004 [קל וחומר] \u0003הוא: ומה בהמה\u0004 שזריקת דם \u0003עולתה למטה\u0004 מחוט הסיקרא, בכל זאת הזאת דם \u0003חטאתה למעלה\u0004 על קרנות המזבח, \u0003עוף שעולתו למעלה אינו דין שחטאתו למעלה?\u0004","\u0003תלמוד לומר\u0004 בחטאת העוף: \u0003\"והנשאר בדם ימצה אל יסוד המזבח\"\u0004 (ויקרא ה, ט), ומכאן יש ללמוד שמזה על \u0003קיר שהשירין שלו מתמצים\u0004 ויורדים \u0003ליסוד, ואיזה? זה קיר התחתון,\u0004 שהרי רובו של הקיר העליון מצוי מעל לסובב.","ושואלים: \u0003ונעביד מעילאי\u0004 \u0005[ושנעשה\u0006 הזאה \u0005מלמעלה]\u0006 לפי הסברה שאמרנו, \u0003והדר נעביד מתתאי\u0004 \u0005[ואחר כך נעשה\u0006 מיצוי \u0005מלמטה],\u0006 ונקיים את האמור בכתוב! \u0003אמר רבא: מי כתיב\u0004 \u0005[האם נאמר]\u0006 \u0003ימצה? ימצה כתיב\u0004 \u0005[נאמר],\u0006 \u0003דממילא\u0004 (שמעצמו) \u0003משמע\u0004 שהדם מתמצה מן הקיר, ויורד אל היסוד, וזה יכול להעשות רק כשממצה את הדם בחציו התחתון של המזבח, מתחת הסובב.","\u0003אמר רב זוטרא בר טוביה אמר רב: כיצד מולקין חטאת העוף?\u0004 מחזיק את העוף מגבו, לרוחב כף ידו, כש\u0003אוחז גפיו\u0004 (כנפיו) \u0003בשתי אצבעות\u0004 בין האצבע והאמה, \u0003ושתי רגלים בשתי אצבעות\u0004 בין הקמיצה והזרת, וראשה נמצא בין האצבע לאגודל, ומכניס אגודלו מתחת לצווארה, \u0003ומותח צוארה על רוחב גודלו ומולקה\u0004 בציפורנו מן העורף.","\u0003במתניתא תנא\u0004 \u0005[בברייתא שנה]:\u0006 \u0003ציפרא מלבר\u0004 \u0005[הצפור מחוץ],\u0006 כלומר, לא כמו שאמרנו, שגוף הציפור נמצא בתוך ידו, אלא על גב ידו לרוחבה, וגבה מופנה אליו, כאשר הוא \u0003אוחז גפיו בשתי אצבעות\u0004 קמיצה וזרת \u0003ושני רגלים בשתי אצבעות\u0004 אצבע ואמה, \u0003ו\u0004באמצעות אגודלו הוא מכופף את ראשה לתוך כף ידו \u0003מותח צוארו על רוחב שתי אצבעותיו ומולק. וזו עבודה קשה שבמקדש\u0004 להחזיק את הגוף כולו ואת צוארו במקום הנכון ולמלוק.","ותוהים: \u0003זו היא ותו לא\u0004 \u0005[ולא עוד]?\u0006 \u0003והאיכא\u0004 \u0005[והרי יש]:\u0006 \u0003קמיצה\u0004 של קומץ המנחה \u0003וחפינה\u0004 של הקטורת ביום הכיפורים, שגם הן עבודות קשות שבמקדש! \u0003אלא אימא\u0004 \u0005[אמור]:\u0006 \u0003זו עבודה קשה,\u0004 אחת \u0003מעבודות קשות שבמקדש.\u0004","\u0003עולת העוף כיצד נעשית? עלה לכבש ופנה לסובב, בא לו לקרן דרומית מזרחית, היה מולק את ראשה ממול ערפה ומבדיל\u0004 לגמרי את הראש מן הגוף, \u0003ומיצה\u0004 (תוך כדי סחיטה) \u0003את דמה על קיר המזבח; נטל את הראש והקיף\u0004 (הצמיד) \u0003בית מליקתו\u0004 (המקום בו נמלק, הצואר) \u0003למזבח\u0004 כדי שיתמצה הדם ממנו, \u0003ספגו\u0004 את הדם שבו \u0003במלח\u0004 שמניח שם \u0003וזרקו על גבי האשים\u0004 (האש שעל המזבח)","\u0003בא לו לגוף, והסיר את המוראה\u0004 (הזפק) \u0003ואת הנוצה\u0004 שעליה, \u0003ואת בני המעיים היוצאין עמם והשליכן לבית הדשן. שיסע\u0004 את העוף לאורכו, \u0003ולא הבדיל\u0004 לא הפריד לגמרי שני חלקי העוף המשוסעים, \u0003ואם הבדיל\u0004 — \u0003כשר. סופגו במלח וזרקו על גבי האשים.\u0004","\u0003לא הסיר המוראה ולא הנוצה ואת בני מעיים היוצאין עמם, ולא ספגו במלח, כל\u0004 דבר \u0003ששינה בה מאחר שמיצה את דמה\u0004 — \u0003כשירה. הבדיל\u0004 את הראש מן הגוף \u0003בחטאת ולא הבדיל בעולה\u0004 — בשניהם \u0003פסול. מיצה\u0004 בעולת העוף \u0003את דם הראש ולא מיצה דם הגוף\u0004 — \u0003פסולה,\u0004 אבל מיצה \u0003דם הגוף ולא מיצה דם הראש\u0004 — \u0003כשירה.\u0004 ומעתה דנים בפסולי מחשבה שבקרבנות העוף.","\u0003חטאת העוף שמלקה שלא לשמה, מיצה דמה שלא לשמה,\u0004 או שעשה זאת \u0003לשמה ו\u0004אחר כך \u0003שלא לשמה, או שלא לשמה ולשמה\u0004 — \u0003פסול,\u0004 כשאר החטאות הנפסלות כשנעשות שלא לשמה (ראה לעיל זבחים יד,א). \u0003עולת העוף\u0004 שעשאה שלא לשמה — \u0003כשירה, ובלבד שלא עלתה לבעלים לשם חובה.\u0004","\u0003אחד חטאת העוף ואחד עולת העוף, שמלקן ושמיצה את דמן לאכול דבר שדרכו לאכול ולהקטיר דבר שדרכו להקטיר,\u0004 אם עשה זאת במחשבה לעשות זאת \u0003חוץ למקומו,\u0004 כלומר, חוץ לעזרה — \u0003פסול ואין בו כרת,\u0004 ואם חישב שיעשה \u0003חוץ לזמנו\u0004 למחרת — \u0003פיגול וחייבין עליו כרת, ובלבד שיקריב המתיר\u0004 (הדם, שמתיר את הבשר להקטרה או לאכילה) \u0003כמצותו,\u0004 שרק אז חל עליו דין פיגול.","\u0003כיצד קרב המתיר כמצותו? מלק בשתיקה\u0004 (שלא במחשבת פסול) \u0003ומיצה הדם\u0004 במחשבת \u0003חוץ לזמנו, או שמלק\u0004 במחשבת \u0003חוץ לזמנו ומיצה הדם בשתיקה, או שמלק ומיצה הדם חוץ לזמנו\u0004 — \u0003זהו שקרב המתיר\u0004","\u0003כמצותו. כיצד לא קרב המתיר כמצותו? מלק\u0004 במחשבת \u0003חוץ למקומו\u0004 ו\u0003מיצה הדם\u0004 במחשבת \u0003חוץ לזמנו, או שמלק חוץ לזמנו ומיצה הדם חוץ למקומו, או שמלק ומיצה הדם חוץ למקומו;\u0004"],["\u0003חטאת העוף שמלקו\u0004 במחשבת \u0003שלא לשמה ומיצה הדם\u0004 במחשבה \u0003חוץ לזמנו, או שמלק חוץ לזמנו ומיצה דמו שלא לשמה, או שמלק ומיצה הדם שלא לשמה\u0004 — \u0003זהו שלא קרב המתיר כמצותו.\u0004","מלק או מיצה את הדם על מנת \u0003לאכול כזית בחוץ\u0004 ו\u0003כזית למחר, כזית למחר\u0004 ו\u0003כזית בחוץ, כחצי זית בחוץ כחצי זית למחר, כחצי זית למחר כחצי זית בחוץ\u0004 — \u0003פסול ואין בו כרת.\u0004","\u0003אמר ר' יהודה, זה הכלל: אם מחשבת הזמן קדמה למחשבת המקום\u0004 — \u0003פיגול וחייבין עליו כרת, ואם מחשבת המקום קדמה למחשבת הזמן\u0004 — \u0003פסול ואין בו כרת; [וחכמים אומרים: זה וזה פסול ואין בו כרת].\u0004","\u0003לאכול כחצי זית ולהקטיר כחצי זית\u0004 — \u0003כשר, שאין אכילה והקטרה מצטרפין.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 על האמור בעולת העוף: \"והקריבו הכהן אל המזבח ומלק את ראשו והקטיר המזבחה\" (ויקרא א, טו), \u0003\"והקריבו\" מה תלמוד לומר?\u0004 מדוע לא נאמר \"והקריב\"?","\u0003לפי שנאמר\u0004 בפסוק הקודם: \"ואם מן העוף קרבנו וכו' \u0003והקריב מן התרים או מן בני היונה\"\u0004 (ויקרא א, יד), \u0003יכול המתנדב עוף לא יפחות משני פרידין\u0004 (שני עופות)? \u0003תלמוד לומר \"והקריבו\"\u0004 בלשון יחיד, לומר: \u0003אפילו פרידה אחת יביא אל המזבח.\u0004","וממשיכים בדרשת הכתוב \u0003מה תלמוד לומר \"הכהן\"\u0004 (ויקרא א, טו)? \u0003לקבוע לו כהן,\u0004 שרק כהן הוא שעושה את המליקה, ולא זר. ומסבירים: \u0003שיכול\u0004 היית לומר \u0003והלא דין\u0004 (קל וחומר) \u0003הוא\u0004 לומר אחרת: \u0003ומה\u0004 עולת \u0003בן צאן שקבע לו צפון\u0004 לשחיטתו (ויקרא א, יא) \u0003לא קבע לו כהן,\u0004 ואף זר כשר לשחוט (ראה לעיל זבחים לב,א), \u0003עוף שלא קבע לו צפון אינו דין שלא יקבע לו כהן? תלמוד לומר \"אל הכהן\" לקבוע לו כהן.\u0004","לפי זה, \u0003יכול ימלקנו בסכין? ו\u0004לכאורה, לפי מה שאמרנו, \u0003דין\u0004 (קל וחומר) \u0003הוא: ומה אם שחיטה שלא קבע לה כהן קבע לה כלי\u0004 שתישחט בסכין (ראה להלן זבחים צז,ב), \u0003מליקה שקבע לה כהן אינו דין שיקבע לה כלי?\u0004","\u0003תלמוד לומר: \"כהן ומלק\",\u0004 שהכהן מולק בידו ולא בכלי. והוא כפי מה ש\u0003אמר ר' עקיבא\u0004 באופן אחר: \u0003וכי תעלה על דעתך שזר קרב לגבי\u0004 \u0005[אצל]\u0006 ה\u0003מזבח,\u0004 שנאמר \"והקריבו הכהן אל המזבח\"? \u0003אלא מה תלמוד לומר \"כהן\"? שתהא מליקה בעצמו של כהן,\u0004 ולא בסכין.","וממשיכים בדרשת הכתוב: \u0003יכול ימלקנה בין מלמעלה\u0004 בחציו העליון של המזבח \u0003בין מלמטה? תלמוד לומר: \"ומלק... והקטיר\u0004 המזבחה\" (ראה להלן צז, טו), להקישם זה לזה, \u0003מה הקטרה\u0004 נעשית על האש \u0003בראש המזבח, אף מליקה בראש המזבח.\u0004","\u0003\"ומלק\"\u0004 — \u0003ממול עורף,\u0004 כלומר, מאחור, בצד הרואה את העורף. \u0003אתה אומר: ממול עורף, או אינו אלא מן הצואר? ודין הוא: נאמר כאן,\u0004 בעולה: \u0003\"ומלק\", ונאמר להלן,\u0004 בחטאת העוף: \u0003\"ומלק\u0004 את ראשו ממול עורפו ולא יבדיל\" (ויקרא ה, ח), \u0003מה להלן ממול עורף, אף כאן ממול עורף.\u0004","ויש לשאול: \u0003אי\u0004 \u0005[אם]\u0006 אתה למד מחטאת, אמור גם כך: \u0003מה להלן,\u0004 בחטאת, \u0003מולק ואינו מבדיל\u0004 את הראש מן הגוף, כפי שנאמר שם, \u0003אף כאן מולק ואינו מבדיל! תלמוד לומר\u0004 בעולה: \u0003\"ומלק והקטיר\"\u0004 (ויקרא א, טו), \u0003מה הקטרה\u0004 — \u0003הראש לעצמו והגוף לעצמו, אף מליקה\u0004 — \u0003הראש לעצמו והגוף לעצמו.\u0004","\u0003ומנין שהקטרת הראש בעצמו והגוף בעצמו? שנאמר\u0004 לגבי הגוף: \"ושסע אותו בכנפיו... \u0003והקטיר אותו\u0004 הכהן המזבחה\" (ויקרא א, יז) — \u0003הרי הקטרת הגוף אמורה, הא מה אני מקיים\u0004 מה שנאמר מתחילה \u0003\"והקטיר המזבחה\"\u0004 (ויקרא א, טו) — \u0003בהקטרת הראש הכתוב מדבר.\u0004 וממשיכה הברייתא בדרשת הפסוק.","מה שנאמר בעולת העוף: \u0003\"ונמצה דמו\"\u0004 (ויקרא א, טו), כוונתו שצריך למצות את כל הדם שבעוף \u0003כולו. \"אל קיר המזבח\"\u0004 (ויקרא א, טו) — \u0003ולא על קיר הכבש ולא על קיר ההיכל. ואיזה\u0004 קיר \u0003זה? זה קיר העליון\u0004 בחציו העליון של המזבח, למעלה מחוט הסיקרא.","ויש לשאול: \u0003או אינו אלא קיר התחתון? ו\u0004לכאורה \u0003דין הוא: מה\u0004 קרבן \u0003בהמה ש\u0004הזאת דם \u0003חטאתה\u0004 \u0003למעלה\u0004 — הזאת דם \u0003עולתה למטה, עוף שחטאתו למטה\u0004 — \u0003אינו דין שעולתו למטה?\u0004","\u0003תלמוד לומר: \"ומלק\u0004 את ראשו \u0003והקטיר... ונמצה דמו\"\u0004 (ויקרא א, טו), \u0003וכי תעלה על דעתך לאחר שהקטיר חוזר וממצה?\u0004 והרי אין מקטירים דבר על המזבח קודם הזאת הדם! \u0003אלא לומר לך: מה הקטרה בראש המזבח, אף מיצוי בראש המזבח\u0004 כלומר, בקיר הסמוך לראש המזבח. \u0003הא\u0004 \u0005[הרי]\u0006 \u0003כיצד? היה עולה בכבש ופונה לסובב ובא לו לקרן דרומית מזרחית, היה מולק את ראשה ממול ערפה ומבדיל, וממצה מדמה על קיר המזבח\u0004 שלידו, כשהוא עומד על הסובב. ומכל מקום \u0003אם עשאה למטה מרגליו\u0004 כלומר, למטה מן הסובב עליו הוא עומד, \u0003אפילו\u0004 במרחק \u0003אמה\u0004 מתחתיו — \u0003כשירה.\u0004","\u0003ר' נחמיה ור' אליעזר בן יעקב אומרים: כל עצמה\u0004 של עולת העוף, ובכלל זה המיצוי, \u0003אין נעשית אלא בראש המזבח.\u0004 ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]?\u0006 מה יסוד מחלוקתם? הרי לשתי הדעות צריך שיעשה המיצוי כמו ההקטרה, בראש המזבח!","\u0003אביי ורבא דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 מחלוקת האם \u0003עושה מערכה על גבי סובב איכא בינייהו\u0004 \u0005[יש ביניהם],\u0006 שלדעת תנא קמא אפשר בשעת הדחק לעשות מערכה על הסובב, ולשיטתו מיצוי הדם באמה שמתחת לסובב סמוך למקום ההקטרה. ואילו ר' נחמיה ור' אליעזר בן יעקב סבורים שמערכה היא רק על ראש המזבח, ולכן המליקה והמיצוי חייבים להיות סמוך לשם.","שנינו במשנה: \u0003בא לו לגוף\u0004 והסיר את המוראה ואת הנוצה ואת בני המעיים היוצאים עמה והשליכם לבית הדשן. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 מה שנאמר בעולת העוף: \u0003\"והסיר את מראתו בנצתה\"\u0004 (ויקרא א, טז), \"מוראתו\" — \u0003זו זפק.\u0004","\u0003יכול יקדיר\u0004 (יחתוך את העור) \u0003בסכין ויטלנו\u0004 את הזפק מתחתיו? \u0003תלמוד לומר \"בנצתה\", נוטל את הנוצה\u0004 (כלומר, גם את העור והנוצה שעליו) \u0003עמה. אבא יוסי בן חנן אומר: נוטלה ונוטל\u0004 גם את \u0003קורקבנה עמה.\u0004","החכם \u0003דבי\u0004 \u0005[של בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל תנא\u0004 \u0005[שנה]:\u0006 \u0003\"בנצתה\"\u0004 — \u0003בנוצה שלה,\u0004 ולא יותר מזה. ולכן \u0003קודרה\u0004 (חותך אותה) \u0003בסכין\u0004 מבחוץ סביב מקום הזפק \u0003כמין ארובה,\u0004 ואת מה שקדר הוא מוליך אל מקום הדשן."],["שנינו במשנה כי לאחר הסרת המוראה ומה שעמה מגוף העולה, \u0003שיסע\u0004 את הגוף \u0003ולא הבדיל.\u0004 ועל הכתוב בענין זה, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 משמעות \u0003\"ושסע\"\u0004 שנאמר במקרא (ויקרא א, יז) — \u0003אין שיסע אלא ביד, וכן הוא אומר: \"וישסעהו כשסע הגדי\u0004 ומאומה אין בידו\" (שופטים יד, ו).","שנינו במשנה: \u0003לא הסיר את המוראה\u0004 וכו' הבדיל בחטאת — פסולה. ומעירים: \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 לפיה אין מבדילים בחטאת, ש\u0003לא\u0004 \u0003כ\u0004שיטת \u0003ר' אלעזר בר' שמעון. דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' אלעזר בר' שמעון: שמעתי שמבדילין בחטאת העוף.\u0004","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]?\u0006 כלומר, במה תלויה מחלוקתם? \u0003אמר רב חסדא: מיצוי\u0004 דם \u0003חטאת העוף\u0004 על קיר המזבח לאחר הזאת הדם, האם הוא \u0003מעכב איכא בינייהו\u0004 \u0005[יש ביניהם],\u0006 ה\u0003תנא קמא\u0004 \u0005[הראשון,\u0006 של משנתנו\u0005]\u0006 \u0003סבר: מיצוי חטאת העוף מעכב, וכיון\u0004 שלאחר שמבדיל עושה בהכרח \u0003מצוי דם,\u0004 נמצא כי \u0003קעביד\u0004 \u0005[עושה]\u0006 \u0003מעשה עולה בחטאת העוף,\u0004 הבדלה ומיצוי, ודבר זה פוסל את החטאת, כפי ששנינו בפרק הבא (סו,א).","\u0003ור' אלעזר בר' שמעון סבר: מיצוי חטאת העוף לא מעכב,\u0004 וגם אם יבדיל יכול הוא שלא למצות את דמה, ולא יהא זה כמעשה עולה, \u0003ו\u0004לפיכך, הבדלה זו שהוא עושה \u0003מחתך בשר בעלמא\u0004 \u0005[בלבד]\u0006 \u0003הוא,\u0004 ואינה נפסלת.","\u0003רבא אמר:\u0004 גם אם שניהם סבורים כי מיצוי חטאת העוף מעכב, דין \u0003שהייה בסימן שני בעולת העוף\u0004 האם הוא \u0003מעכב\u0004 (פוסל) \u0003איכא בינייהו\u0004 \u0005[יש ביניהם],\u0006 אם שהה במליקה בין סימן ראשון לשני, כפי שמליקת החטאת נעשית (כמבואר להלן, שכשחותך את הסימן הראשון חותך עמו את רוב הבשר שבצואר העוף, ויש בכך שהייה), ה\u0003תנא קמא סבר\u0004 \u0005[הראשון סבור]:\u0006 \u0003שהייה בסימן שני בעולת העוף לא מעכב\u0004 (לא פוסל), \u0003ו\u0004אם כן, כאשר מבדיל בחטאת העוף, \u0003אף על גב דשהייה\u0004 \u0005[אף על פי ששוהה בו בסימן השני] —\u0006 \u0003קא עביד\u0004 \u0005[הריהו עושה]\u0006 \u0003מעשה עולה בחטאת,\u0004 ופסולה.","\u0003ור' אלעזר בר' שמעון סבר:\u0004 השיהוי \u0003מעכב\u0004 ופוסל בעולת העוף. \u0003וכיון\u0004 שכשמולק את החטאת בהכרח \u0003שהייה\u0004 \u0005[שהה בו]\u0006 בסימן השני — אין זה מעשה עולה, וכשהוא חותכו — \u0003מחתך בשר בעלמא\u0004 \u0005[בלבד]\u0006 \u0003הוא.\u0004","\u0003אביי אמר:\u0004 כולם מודים ששהייה פוסלת בעולה, ואולם נחלקו האם בהכרח יש שהייה בחטאת. ובשאלה \u0003האם\u0004 \u0003רוב בשר מעכב איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 מחלוקת\u0005]\u0006 כלומר, מה יהא הדין אם לא חתך את רוב בשר הצואר לאחר חיתוך הסימן הראשון, כפי שצריך לעשות בחטאת. לדעת תנא קמא אין זה מעכב, ואם לאחר הסימן הראשון אינו שוהה בחיתוך רוב הבשר, וחותך מיד את הסימן השני — נמצא שהוא עושה מעשה עולה, ופוסל. ולדעת ר' אלעזר בר' שמעון דין זה מעכב, וכיון שאי אפשר בלא שהייה בחטאת נמצא שגם אם הוא מבדיל אינו עושה בה מעשה עולה.","ומעירים: \u0003ו\u0004רבא ואביי נחלקו \u0003בפלוגתא\u0004 \u0005[ובמחלוקת]\u0006 של \u0003ר' זירא ור' שמואל בר רב יצחק,\u0004 \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: שהייה בסימן שני בעולת העוף מעכב איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 בין התנא של משנתנו לבין ר' אלעזר בר' שמעון, \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: רוב בשר מעכב איכא בינייהו\u0004 \u0005[יש ביניהם].\u0006","ושואלים: כיון שנחלקו אם רוב בשר מעכב, \u0003מכלל\u0004 הדברים משמע \u0003דבעינן\u0004 \u0005[שצריכים אנו]\u0006 לדעת הכל שיחתוך \u0003רוב בשר בתחילה\u0004 (לכתחילה)? ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003והתניא\u0004 \u0005[ו\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003כיצד מולקין חטאת העוף?\u0004 כשהוא מולק בצפורנו מצד העורף \u0003חותך\u0004 חוט \u0003שדרה ומפרקת\u0004 (עמוד השדרה\u0003)\u0004 \u0003בלא רוב בשר עד שמגיע לוושט או לקנה, הגיע לוושט או לקנה, חותך סימן אחד או רובו ורוב בשר עמו, ובעולה\u0004 — חותך \u0003שנים\u0004 (שני סימנים) \u0003או רוב שנים.\u0004 עד כאן נסוב הדיון לפי ההבנה, שלדעת ר' אלעזר בר' שמעון, אף שלכתחילה אין להבדיל בחטאת, מכל מקום כשר הדבר בדיעבד.","ומסופר, \u0003אמרוה קמיה\u0004 \u0005[אמרו אותה\u0006 מחלוקת האמוראים \u0005לפני]\u0006 \u0003ר' ירמיה, אמר: לא שמיע להו\u0004 \u0005[האם לא שמעו]\u0006 \u0003הא\u0004 \u0005[\u0006הלכה \u0005זו]\u0006 ש\u0003אמר ר' שמעון בן אליקים משום\u0004 (בשם) \u0003ר' אלעזר בן פדת משום ר' אלעזר בן שמוע, אומר היה ר' אלעזר בר' שמעון: שמעתי בחטאת העוף שמבדילין,\u0004 שאין כלל איסור להבדיל. \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"לא יבדיל\"\u0004 האמור בתורה לגבי חטאת העוף (ויקרא ה, ח)?"],["\u0003אין צריך להבדיל\u0004 כפי שצריך לעשות בעולת העוף. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי: אלא מעתה, גבי\u0004 \u0005[אצל]\u0006 דין \u0003בור דכתיב\u0004 \u0005[שנאמר]:\u0006 \"וכי יפתח איש בור... \u0003ולא יכסנו\"\u0004 (שמות כא, לג), \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר ש\u0003אין צריך לכסות\u0004 ואין זה ציווי?","ודוחים: \u0003הכי השתא\u0004 \u0005[כך אתה משווה]?!\u0006 \u0003התם\u0004 \u0005[שם,\u0006 בבור\u0005],\u0006 \u0003כיון דכתיב\u0004 \u0005[שנאמר]\u0006 אחר כך: \u0003\"בעל הבור ישלם\"\u0004 (שמות כא, לד), מכאן אתה למד כי \u0003עלויה\u0004 \u0005[עליו]\u0006 \u0003הוא דרמי לכסויי\u0004 \u0005[שמוטל לכסות]\u0006 את הבור מתחילה. \u0003אבל הכא\u0004 \u0005[כאן],\u0006 \u0003מכדי כתיב\u0004 \u0005[הואיל ונאמר]\u0006 בעולת העוף: \u0003\"והקריבו\"\u0004 (ויקרא א, טו), ומכאן למדנו כי \u0003חלק הכתוב בין חטאת העוף לעולת העוף\u0004 שציותה התורה להבדיל בה, לומר: דווקא אותו מקריבים באופן זה, שמבדיל, אבל לא בחטאת.","אם כן מה שנאמר בחטאת העוף \u0003\"לא יבדיל\"\u0004 (ויקרא ה, ח) \u0003למה לי? שמע מינה\u0004 \u0005[למד מכאן]\u0006 שאין כאן איסור, אלא אמירה ש\u0003אין צריך להבדיל.\u0004","שנינו: \u0003מיצה דם הגוף\u0004 ולא מיצה דם הראש — כשירה, אבל אם מיצה דם הראש ולא מיצה דם הגוף — פסולה. ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר בעולת העוף \u0003\"עולה\"\u0004 (ויקרא א, יז) — \u0003אף על פי שמיצה דם הגוף ולא מיצה דם הראש, יכול מיצה דם הראש ולא מיצה דם הגוף? תלמוד לומר: \"הוא\"\u0004 (ויקרא א, יז).","ושואלים: \u0003מאי תלמודא\u0004 \u0005[מהו התלמוד]?\u0006 כיצד נלמד הדבר מן הכתוב? \u0003אמר רבינא:\u0004 אין ראיה מגוף הכתובים, אבל \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 הדבר, משום ש\u0003רוב דמים בגוף שכיחי\u0004 \u0005[מצויים],\u0006 ולכן תלוי המיצוי בדם שיש בו.","","\u0003חטאת העוף שעשאה למטה\u0004 מחוט הסיקרא שבאמצע המזבח, שהוא מקומה הראוי, אם עשאה \u0003כמעשה חטאת\u0004 במליקה ובהזאה \u0003לשם חטאת\u0004 — \u0003כשירה,\u0004 שכך צריך לעשותה לכתחילה. ואולם אם עשאה למטה \u0003כ\u0004כל \u0003מעשה חטאת\u0004 העוף, אך עשאה \u0003לשם עולה,\u0004 או שעשאה \u0003כמעשה עולה\u0004 אף שעשאה \u0003לשם חטאת,\u0004 או שעשאה \u0003כמעשה עולה לשם עולה\u0004 — בכל אלה הריהי \u0003פסולה.\u0004 ואם \u0003עשאה למעלה, כמעשה כולן\u0004 (בכל אחד מן האופנים שנשנו לפני כן) — \u0003פסולה,\u0004 לפי שעשאה שלא במקומה.","","\u0003עולת העוף שעשאה למעלה\u0004 מחוט הסיקרא, שהוא מקומה הראוי, \u0003כמעשה עולה\u0004 \u0003לשם עולה\u0004 — \u0003כשירה. כמעשה עולה לשם חטאת\u0004 — \u0003כשירה, ובלבד שלא עלתה לבעליה,\u0004 כשאר קרבנות (חוץ מן החטאת והפסח) שאין נפסלים אם נעשו שלא לשמה, אלא שלא עלו לבעלים לשם חובה.","אם עשאה למעלה \u0003כמעשה חטאת לשם עולה,\u0004 או שעשאה \u0003כמעשה חטאת לשם חטאת\u0004 — \u0003פסולה. עשאה למטה כמעשה כולן\u0004 — \u0003פסולה.\u0004"],["נאמר במשנה שאם עשה חטאת העוף למטה כמעשה עולת העוף הריהי פסולה. ומבררים: \u0003דשני במאי\u0004 \u0005[ששינה במה,\u0006 באיזו עבודה של חטאת העוף\u0005]\u0006 עשה כמעשה עולה ופסל? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003דשני\u0004 \u0005[ששינה]\u0006 \u0003במליקה\u0004 שבשעה שמלק הבדיל הראש מן הגוף בחיתוך שני הסימנים, כדרך שנעשית בעולת העוף, אם כן \u0003נימא\u0004 \u0005[\u0006האם \u0005נאמר,\u0006 נסיק מכאן\u0005]\u0006 שמשנתנו היא ש\u0003לא כ\u0004שיטת \u0003ר' אלעזר בר' שמעון,\u0004 ש\u0003אמר: שמעתי שמבדילין בחטאת העוף?\u0004","ותמהים: ומה הקושי שבדבר, \u0003ו\u0004האם \u0003לא אוקימנא\u0004 \u0005[העמדנו]\u0006 את המשנה בפרק הקודם (סה,א) בענין מליקה ש\u0003לא כר' אלעזר בר' שמעון?\u0004","ודוחים: \u0003לא,\u0004 כאן אין הכרח לומר שהמשנה אינה כשיטתו, שכן אפשר שמדובר במקרה \u0003דשני\u0004 \u0005[ששינה]\u0006 \u0003בהזאה\u0004 כלומר, שלא היזה תחילה את הדם כדרך עבודת חטאת העוף, אלא מיצה (סחט) את הדם מצווארה, כעולה, ובמקרה זה אף ר' אלעזר בר' שמעון סבור שהיא פסולה.","ומוסיפים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר],\u0006 שמדובר במשנתנו ששינה בהזאה, \u0003מדקתני סיפא\u0004 \u0005[מ\u0006מה \u0005ששנה\u0006 ב\u0005סוף\u0006 המשנה\u0005]:\u0006 \u0003עשאה\u0004 (לחטאת העוף) \u0003למעלה כמעשה כולן\u0004 — \u0003פסולה, ואפילו כמעשה חטאת לשם חטאת.\u0004 ויש לברר: \u0003דשני במאי\u0004 \u0005[ששינה במה]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003דשני\u0004 \u0005[ששינה]\u0006 \u0003במליקה,\u0004 שעשאה למעלה — \u0003האמר מר\u0004 \u0005[הרי אמר החכם]\u0006 בענין חטאת העוף: \u0003מליקה בכל מקום במזבח כשירה! אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר איפוא \u0003דשני\u0004 \u0005[ששינה]\u0006 \u0003בהזאה,\u0004 ועשאה למעלה. \u0003ומדסיפא\u0004 \u0005[ומ\u0006תוך שב\u0005סוף\u0006 המשנה\u0005]\u0006 מדובר \u0003בהזאה,\u0004 יש לומר כי \u0003רישא נמי\u0004 \u0005[\u0006ב\u0005ראש\u0006 המשנה \u0005גם כן]\u0006 מדובר \u0003בהזאה.\u0004","ודוחים: \u0003מידי איריא? הא כדאיתא והא כדאיתא\u0004 \u0005[כלום שייכים הדברים? זה כפי שהוא וזה כפי שהוא]!\u0006 אף שבסוף המשנה השינוי הוא בהזאה, בתחילת המשנה ייתכן והשינוי הוא במליקה, ואין משנתנו כשיטת ר' אלעזר בר' שמעון.","שנינו במשנה שאם עשה \u0003עולת העוף\u0004 כמעשה חטאת — הריהי פסולה. ומבררים: \u0003דשני במאי\u0004 \u0005[ששינה במה]?\u0006 מה עשה בה כמעשה חטאת?","\u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003דשני\u0004 \u0005[ששינה]\u0006 \u0003במליקה\u0004 שלא הבדיל את הראש מהגוף, אם כן \u0003מדקתני סיפא\u0004 \u0005[מ\u0006מה \u0005ששנינו בסוף\u0006 המשנה\u0005]:\u0006 \u0003כולן\u0004 (כל אלו המקרים שנשנו במשנה) \u0003אין מטמאין\u0004 את האדם בעת שכזית מהקרבן נתון \u0003בבית הבליעה\u0004 שלו, \u0003ומועלין בהן\u0004 (שהנהנה מהם חייב עליהם משום מעילה), \u0003נימא\u0004 \u0005[נאמר]\u0006 שמשנתנו היא ש\u0003לא כר' יהושע, דאי\u0004 \u0005[שאם]\u0006 \u0003כר' יהושע, האמר\u0004 \u0005[הרי אמר]\u0006 בהמשך, לגבי עולה שעשאה למטה כמעשה חטאת: \u0003אין מועלין!\u0004","\u0003ואלא\u0004 יש לומר שמדובר כאן כששינה \u0003במיצוי\u0004 הדם, שמלקה כעולה, אך היזה דמה תחילה כמעשה חטאת, ולא מיצהו. ובמקרה זה, גם לשיטת ר' יהושע מועלים בה.","אך מצד אחר \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סוף\u0006 המשנה\u0005],\u0006 במשנה הבאה: \u0003עולת העוף שעשאה\u0004 \u0003למטה כמעשה חטאת לשם חטאת\u0004 — \u0003ר' אליעזר אומר: מועלין בה, ר' יהושע אומר: אין מועלין בה.\u0004 ויש לברר: \u0003דשני במאי\u0004 \u0005[ששינה במה]?\u0006","\u0003אילימא\u0004 \u0005[אם תאמר]\u0006 ששינה \u0003במיצוי,\u0004 על כך יש להקשות: \u0003אימר\u0004 \u0005[אמור]\u0006 ש\u0003אמר ר' יהושע\u0004 את שיטתו שאין מועלים בה, הרי זה דווקא \u0003דשני\u0004 \u0005[\u0006כ\u0005ששינה]\u0006 \u0003במליקה\u0004, שכאשר מלק סימן אחד כדרך חטאת העוף, למטה, נעקר ממנה שם עולת העוף, ולכן אין מועלים בה, כדין חטאת העוף שנמלקה. ואולם אם לא שינה במליקה, אלא הבדיל כדין עולה, ורק שינה לאחר מכן \u0003במיצוי, מי\u0004 \u0005[האם]\u0006 \u0003אמר\u0004 ר' יהושע שאין מועלים בה?","\u0003ואלא\u0004 בהכרח מדובר כאן בשינוי \u0003במליקה.\u0004 ואולם על כך יש לתמוה: משנה זו \u0003רישא\u0004 \u0005[ראשה,\u0006 תחילתה\u0005]\u0006 בענין חטאת שעשאה כמעשה עולה, \u0003וסיפא\u0004 \u0005[וסופה],\u0006 מחלוקת ר' אליעזר ור' יהושע במשנה הבאה, עוסקים בשינוי \u0003במליקה, ו\u0004אילו \u0003מציעתא\u0004 \u0005[אמצעיתה],\u0006 בענין עולת העוף שעשאה כחטאת, עוסקת כששינה \u0003במיצוי?\u0004","ומשיבים: \u0003אין\u0004 \u0005[\u0006אכן \u0005כן],\u0006 \u0003רישא וסיפא\u0004 \u0005[ראש וסוף\u0006 המשנה\u0005]\u0006 \u0003במליקה, ומציעתא\u0004 \u0005[ואמצע\u0006 המשנה\u0005]\u0006 \u0003במיצוי.\u0004","\u0003וכולן\u0004 כל המקרים שנשנו במשנה הקודמת בקרבנות העוף שנעשה בהם שינוי, אף שהם פסולים ואסורים בהקרבה ובאכילה, \u0003אין\u0004 הן \u0003מטמאין\u0004 כשאר נבלת עוף טהור כשהיא \u0003בבית הבליעה\u0004 של האוכל ממנה, שכן המליקה הוציאתן מכלל נבילה. \u0003ו\u0004מכל מקום, כיון שלא הותרו לכהנים \u0003מועלים בהן\u0004 כלומר, הנהנה מהם מעל, \u0003חוץ מחטאת העוף שעשאה למטה כמעשה חטאת לשם חטאת,\u0004 שכיון שנעשתה כראוי והרי היא מותרת מעתה באכילה לכהנים, אין בה דין מעילה.","\u0003עולת העוף שעשאה למטה\u0004 מחוט הסיקרא שבאמצע המזבח, כדין חטאת, ו\u0003כמעשה חטאת\u0004 שלא חתך אלא סימן אחד, ועשה זאת \u0003לשם חטאת\u0004 — \u0003ר' אליעזר אומר: מועלים בה,\u0004 שהרי עולה היא, ואין בה היתר לכהנים כלל. \u0003ר' יהושע אומר: אין מועלים בה,\u0004 שכיון שעשה בה מעשה חטאת, בעבודותיה ובמקומה ובשמה, הריהי נעשית כחטאת לענין מעילה.","\u0003אמר ר' אליעזר\u0004 לר' יהושע: \u0003ו\u0004הרי קל וחומר הוא זה, שכן \u0003מה אם חטאת שאין מועלים בה\u0004 כאשר היא נעשית \u0003לשמה,\u0004 מכל מקום \u0003כששינה את שמה\u0004 ועשאה לשם עולה — \u0003מועלים בה. עולה,\u0004 \u0003שמועלים בה\u0004 כאשר היא נעשית \u0003לשמה,\u0004 כראוי, \u0003כששינה את שמה\u0004 — \u0003אינו דין שימעלו בה?\u0004","\u0003אמר לו ר' יהושע\u0004 לר' אליעזר: \u0003לא,\u0004 קל וחומר זה יש בו פירכה, שהרי \u0003אם אמרת\u0004 שיש דין מעילה \u0003בחטאת ששינה את שמה לשם עולה,\u0004 טעם הדבר הוא — \u0003שכן שינה את שמה לדבר שיש בו מעילה,\u0004 האם \u0003תאמר\u0004 כן \u0003בעולה ששינה את שמה לשם חטאת? שכן\u0004 הרי \u0003שינה את שמה לדבר שאין בו מעילה!\u0004"],["\u0003אמר לו ר' אליעזר: והרי קדשי קדשים ששחטן\u0004 שלא בצפון העזרה, שהוא מקומם הראוי, אלא \u0003בדרום, ושחטן לשם קדשים קלים\u0004 ששחיטתם בכל העזרה, \u0003יוכיחו\u0004 כשיטתי. \u0003שכן\u0004 אף ש\u0003שינה את שמם\u0004 של קדשי הקדשים \u0003לדבר שאין בו מעילה\u0004 שאין מעילה בבשרם של קדשים קלים, בכל זאת \u0003מועלין בהן,\u0004 כדין קדשי קדשים. \u0003אף אתה אל תתמה על\u0004 שיטתי בדין \u0003העולה\u0004 (עולת העוף) שעשאה כמעשה חטאת העוף, ש\u0003אף על פי ששינה שמה ל\u0004שם חטאת העוף, שהיא \u0003דבר שאין בו מעילה, שימעלו בה!\u0004","\u0003אמר לו ר' יהושע: לא,\u0004 אין מכאן ראיה, שכן \u0003אם אמרת בקדשי קדשים ששחטן בדרום ושחטן לשם קדשים קלים\u0004 שמועלים בהם, טעם הדבר הוא — \u0003שכן שינה את שמם לדבר שיש בו איסור והיתר,\u0004 שהרי בקדשים קלים, אף שאין מועלים בבשרם, מועלים באימוריהם לאחר זריקת הדם, האם \u0003תאמר\u0004 כן גם \u0003בעולה ששינה את שמה לדבר שכולו היתר?\u0004 שהרי חטאת העוף נאכלת כולה, ואין בה איפוא כל צד של מעילה.","בענין המחלוקת שנשנתה במשנה בין ר' אליעזר ור' יהושע, \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 ובה נוסח מורחב יותר של הדיון שביניהם. \u0003אמר לו ר' אליעזר לר' יהושע: אשם ששחטו בצפון\u0004 העזרה \u0003לשם שלמים, יוכיח\u0004 כשיטתי, \u0003ש\u0004הרי \u0003שינה את שמו\u0004 לשם קרבן שאין מועלים בו, \u0003ו\u0004בכל זאת \u0003מועלין בו. ואף אתה אל תתמה על העולה\u0004 (עולת העוף) שעשאה כחטאת העוף, \u0003שאף על פי ששינה את שמה\u0004 לקרבן שאין בו מעילה, דינה הוא \u0003שימעלו בה!\u0004","\u0003אמר לו ר' יהושע: לא,\u0004 אין זו ראייה לשיטתך, שכן \u0003אם אמרת באשם\u0004 ששחטו לשם שלמים, שהדין כן, הרי זה משום \u0003ש\u0004גם \u0003אם שינה את שמו,\u0004 מכל מקום הרי \u0003לא שינה את מקומו,\u0004 שהרי שחטו בצפון, כדינו, האם \u0003תאמר\u0004 כן גם \u0003בעולה\u0004 (עולת העוף) שעשאה למטה כחטאת העוף ולשם חטאת העוף, \u0003ששינה\u0004 גם \u0003את שמה ו\u0004גם \u0003שינה את מקומה?\u0004","חזר ו\u0003אמר לו ר' אליעזר\u0004 לר' יהושע ראייה אחרת: \u0003אשם ששחטו בדרום לשם שלמים יוכיח, ש\u0004הרי בכך \u0003שינה\u0004 גם \u0003את שמו ושינה\u0004 גם \u0003את מקומו, ו\u0004מכל מקום \u0003מועלין בו,\u0004 כאשם. אם כן \u0003אף אתה אל תתמה על העולה\u0004 (עולת העוף) שעשאה למטה כחטאת העוף ולשם חטאת העוף, \u0003שאף על פי ששינה את שמה ושינה את מקומה\u0004 דינה הוא ש\u0003מועלין בה!\u0004","\u0003אמר לו ר' יהושע: לא,\u0004 אף זו אינה ראייה לשיטתך, שכן \u0003אם אמרת\u0004 שהדין כן \u0003באשם\u0004 ששחטו לשם שלמים בדרום, \u0003ששינה את שמו ושינה את מקומו ו\u0004אולם \u0003לא שינה את מעשיו,\u0004 האם \u0003תאמר\u0004 כן \u0003בעולה\u0004 (עולת העוף) שעשאה כחטאת העוף ולשם חטאת העוף למטה, \u0003ששינה את שמה ואת מעשיה ושינה את מקומה?\u0004 עד כאן דברי הברייתא, ולפיה לא השיב ר' אליעזר לר' יהושע על טענתו זו.","ו\u0003אמר רבא\u0004 מדוע? \u0003ונימא ליה\u0004 \u0005[ויאמר לו]:\u0006 \u0003אשם ששחטו בדרום לשם שלמים בשינוי בעלים\u0004 כלומר, לשם אדם אחר, יוכיח, \u0003ש\u0004הרי גם דבר זה נחשב כאילו \u0003שינה את שמו ושינה את מקומו ושינה את מעשיו,\u0004 ומכל מקום מועלים בו!","\u0003מדלא קאמר ליה הכי\u0004 \u0005[מ\u0006תוך \u0005שלא אמר לו כך],\u0006 \u0003שמע מינה נחית\u0004 \u0005[למד מכאן\u0006 שבשלב זה של הדיון \u0005ירד,\u0006 הגיע\u0005]\u0006 והבין \u0003ר' אליעזר לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 של \u0003ר' יהושע,\u0004 שמה שהשיב לו על ראיותיו לא היה עיקר טעמו, אלא כמו ש\u0003אומר רב אדא בר אהבה, אומר היה ר' יהושע: עולת העוף שעשאה למטה כמעשה חטאת לשם חטאת, כיון\u0004 כלומר, משעה \u0003שמלק בה סימן אחד\u0004 במקום חטאת העוף ולשם חטאת העוף, \u0003נמשכת ונעשית חטאת העוף.\u0004","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 לדרך זו, \u0003חטאת העוף נמי\u0004 \u0005[גם כן]\u0006 \u0003שעשאה למעלה כמעשה העולה, מכי מליק\u0004 \u0005[מכאשר מלק]\u0006 \u0003בה סימן אחד תימשך ותהוי\u0004 \u0005[ותהיה]\u0006 \u0003עולת העוף!\u0004 \u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003הכי נמי\u0004 \u0005[\u0006אכן \u0005כך\u0006 הוא \u0005גם כן],\u0006 \u0003והא אמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן משום\u0004 \u0005[בשם]\u0006 \u0003ר' בנאה: כך היא הצעה\u0004 (נוסחה המדוייק) \u0003של משנה\u0004 זו, כך שונים אותה, כפי שהיא לפנינו, \u0003מאי לאו\u0004 \u0005[האם אין]\u0006 כוונתו ש\u0003כך היא הצעה, ותו לא\u0004 \u0005[ולא עוד],\u0006 שלא נחלק ר' יהושע במשנתנו, והכשיר, אלא בעולת העוף שעשאה למטה כמעשה חטאת העוף לשם חטאת העוף?","ודוחים: \u0003לא, כך הצעה של כולה משנה,\u0004 שכשם שנחלק בעולת העוף שעשאה במקום חטאת, כמעשה חטאת ולשם חטאת — כך נחלק אף בחטאת העוף שעשאה במקום עולה, כמעשה עולה, ולשם עולה, שלדעתו נמשכה לשם עולה.","\u0003רב אשי אמר:\u0004 אפשר לדחות קושיה זו באופן אחר, ולומר שאכן לא נחלק ר' יהושע אלא בעולת העוף שעשאה כחטאת העוף, אבל לא בחטאת העוף שעשאה כעולת העוף, משום שיש להבחין בין המקרים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003עולת העוף שעשאה למטה כמעשה חטאת לשם חטאת, כיון דהא\u0004 \u0005[שזו,\u0006 חטאת העוף\u0005]\u0006 \u0003הכשירה ב\u0004מליקת \u0003סימן אחד, והא\u0004 \u0005[וזו,\u0006 עולת העוף\u0005]\u0006 \u0003הכשירה ב\u0004מליקת \u0003שני סימנין, ו\u0004כן משום ש\u0003עולת העוף למטה ליתא\u0004 \u0005[אין],\u0006 לכן \u0003כיון\u0004 ש\u0003מלק בה סימן אחד\u0004 כמעשה חטאת ובמקום חטאת, ולשם חטאת — הריהי \u0003נמשכת ונעשית חטאת העוף.\u0004","\u0003אלא חטאת העוף\u0004 שמלק אותה למעלה לשם עולה, \u0003כיון\u0004 ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003מליקה בכל מקום\u0004 במזבח \u0003כשירה\u0004 בחטאת, \u0003מכי מלק\u0004 \u0005[מכאשר מלק]\u0006 \u0003בה סימן אחד\u0004 לשם עולה כבר \u0003איפסלא\u0004 \u0005[נפסלה],\u0006 כדין חטאת שנעשתה שלא לשמה. ומעתה \u0003כי הדר מליק באידך סימן\u0004 \u0005[כאשר חזר מלק בסימן האחר]\u0006 כמעשה עולת העוף, \u0003היכי ממשכה והויא\u0004 \u0005[איך\u0006 היא \u0005נמשכת ונהיית]\u0006 \u0003עולת העוף?\u0004","ושבים לשיטה שהובאה למעלה, ודנים בה \u0003גופא\u0004 \u0005[לגופה]:\u0006 \u0003אמר רב אדא בר אהבה, אומר היה ר' יהושע: עולת העוף שעשאה למטה כמעשה חטאת לשם חטאת, כיון שמלק בה סימן אחד נמשכת ונעשית חטאת העוף.\u0004"],["ומעתה מבררים האם אכן שיטתו של ר' יהושע היא כהסברו של רב אדא בר אהבה. ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו במשנה במסכת קינים: שתי נשים יולדות (שכל אחת מהן חייבת, כדין יולדת, להביא שתי תורים או שני בני יונה, אחד לחטאת העוף ואחד לעולת העוף) שהביאו כבר מחצית חובתן (האחת, הביאה עולתה והאחרת הביאה חטאתה), ועתה הביאו כהשלמת חובתן קן ובו שני גוזלות, וקבעו כי גוזל זה ישמש \u0003חטאת לזו\u0004 שהביאה כבר עולתה, \u0003ו\u0004גוזל זה ישמש \u0003עולה לזו\u0004 שהביאה חטאתה, והתערבו הגוזלות.","אם \u0003עשה\u0004 הכהן המקריב את \u0003שתיהן למעלה\u0004 מחוט הסיקרא שבמזבח, וכדין עולת העוף — \u0003מחצה\u0004 (אחד מהם, העולה) \u0003כשר, ומחצה\u0004 (אחד מהם, החטאת) \u0003פסול.\u0004 וכיוצא בזה, אם עשה הכהן המקריב את \u0003שתיהן למטה\u0004 מחוט הסיקרא שבמזבח, וכדין חטאת העוף — \u0003מחצה כשר ומחצה פסול,\u0004 שכן הגוזל לחטאת העוף הוקרב כדינו, ואילו הגוזל לעולת העוף נפסל. אבל אם עשה הכהן \u0003אחת למעלה ואחת למטה\u0004 — \u0003שתיהן פסולות, ש\u0004כן \u0003אני\u0004 חושש ו\u0003אומר:\u0004 אפשר וזו שנועדה ל\u0003חטאת קרבה למעלה\u0004 ונפסלה בכך, \u0003ו\u0004זו שנועדה ל\u0003עולה קרבה למטה\u0004 ונפסלה אף היא.","ואולם להסברו של רב אדא בר אהבה בשיטת ר' יהושע יש לשאול: \u0003נהי נמי\u0004 \u0005[גם אם אמנם]\u0006 \u0003עולה קרבה למטה\u0004 מה בכך? \u0003תימשוך ותהוי\u0004 \u0005[תימשך\u0006 משם עולה \u0005ותהיה]\u0006 זאת \u0003חטאת העוף!\u0004","ודוחים: אין מכאן ראיה, שכן \u0003אימור\u0004 \u0005[אמור]\u0006 ש\u0003אמר ר' יהושע\u0004 שנעקרה עולת העוף ונעשית חטאת העוף, דווקא \u0003ב\u0004מקרה של \u0003חד גברא\u0004 \u0005[איש אחד]\u0006 שכהן עושה את עולתו למטה לשם חטאתו, ואולם \u0003בתרי גברי\u0004 \u0005[בשני אנשים]\u0006 שונים, שהכהן מקריב את עולתו של אחד לשם חטאתו של אחר, \u0003מי\u0004 \u0005[האם]\u0006 גם כן \u0003אמר?\u0004","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו עוד במסכת קינים: שתי יולדות שהביאו בשותפות את קיניהן באופן זה: קן אחד שיש בו גוזל ל\u0003חטאת ו\u0004גוזל ל\u0003עולה\u0004 (אבל לא נקבע של מי החטאת ושל מי העולה), \u0003ו\u0004קן \u0003סתומה\u0004 (שלא נקבע איזה מהם לחטאת ואיזה לעולה), \u0003ו\u0004קן \u0003מפורשת\u0004 (שנקבע איזה מהם לחטאת ואיזה לעולה, וגם נקבע מי הבעלים של כל גוזל).","אם \u0003עשה\u0004 הכהן את \u0003כולן למעלה\u0004 מחוט הסיקרא, וכדין עולת העוף — \u0003מחצה כשר\u0004 (שלושה גוזלות שנועדו לעולת העוף) \u0003ומחצה פסול\u0004 (שלושה גוזלות שנועדו לחטאת העוף). וכיוצא בזה, אם עשה את \u0003כולן למטה\u0004 — \u0003מחצה כשר\u0004 (שלושת הגוזלות לחטאת) \u0003ומחצה פסול\u0004 (שלושת הגוזלות לעולה). אם עשה את \u0003חציין\u0004 של כל קן וקן \u0003למעלה וחציין למטה\u0004 — \u0003אינה כשירה\u0004 מכל שלש הקינים \u0003אלא סתומה,\u0004 שלא נתפרש בה מי לחטאת ומי לעולה, והכהן בעצם עשייתו קובע שהגוזל שנעשה למעלה הוא עולת העוף וזה שנעשה למטה הוא חטאת העוף. \u0003ומתחלקת\u0004 הקן הסתומה \u0003ביניהן,\u0004 שהרי שותפות הן בקן זו, והאחת יצאה בה ידי חטאתה והשנית יצאה בה ידי עולתה.","ונדייק: דווקא הקן הסתומה היא שכשירה, \u0003ואילו\u0004 הגוזלות ה\u0003מפורשין\u0004 לחטאת ולעולה \u0003לא\u0004 כשירים, שמא העולות נעשו למטה והחטאות למעלה. ולהסברו של רב אדא בר אהבה בשיטת ר' יהושע, יש לשאול על כך: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 הם פסולים? הרי \u0003נהי נמי\u0004 \u0005[גם אם אמנם]\u0006 \u0003עולה קרבה למטה,\u0004 מה בכך, \u0003תימשוך ותיהוי\u0004 \u0005[תימשך\u0006 משם עולה \u0005ותהיה]\u0006 זאת \u0003חטאת העוף!\u0004","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003הא\u0004 \u0005[\u0006משנה \u0005זו]\u0006 היא ש\u0003לא כ\u0004שיטת \u0003ר' יהושע, ו\u0004אולם \u0003מי מצית אמרת הכי\u0004 \u0005[האם יכול אתה לומר כך]?\u0006","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראייה שמשניות מסכת קינים הינן בשיטת ר' יהושע, שכן שנינו שם בהמשך המשניות: \u0003האשה שאמרה\u0004 בהיותה בהריון: \u0003\"הרי עלי\u0004 בנדבה \u0003קן\u0004 (זוג תורים או בני יונה) \u0003אם אלד זכר\"\u0004 נוסף על הקן שכל יולדת חייבת בו — אם אכן \u0003ילדה זכר, מביאה שתי קינים, אחת ל\u0004קיום \u0003נדרה ואחת לחובתה.\u0004","\u0003נתנתן לכהן\u0004 את ארבעת הגוזלות, ולא פירשה מה חטאת ומה עולה — \u0003הכהן צריך לעשותן שלש\u0004 גוזלות \u0003למעלה\u0004 מחוט הסיקרא, וכדין עולת העוף (קן נדבה שכולו עולת העוף, וגוזל אחד מקן החובה) \u0003ואחת\u0004 הגוזלות צריך לעשות \u0003למטה,\u0004 כדין חטאת העוף.","אם \u0003לא עשה כן, אלא עשה שתים למעלה ושתים למטה, ו\u0004עשה כן כיון ש\u0003לא נמלך\u0004 באשה, וחשב שאלו הן שתי קיני חובה — \u0003צריכה שתביא עוד פרידה\u0004 (גוזל) \u0003אחת, ו\u0004אותה פרידה נוספת \u0003תקריבנה למעלה\u0004 לשם עולה.","כל זה אמור כאשר ארבעת הגוזלים שבשתי הקינים היו כולם \u0003ממין אחד\u0004 (בני יונה או תורים). \u0003ו\u0004אולם אם היו \u0003משני מינין\u0004 (בקן אחד שני תורים, ובקן האחר שני בני יונה), והכהן הקריב מכל מין אחד למעלה ואחד למטה, ואינו זוכר איזו קן הקריב תחילה — \u0003תביא שתים\u0004 פרידות, תור ובן יונה, ויקריבן למעלה. שכן הקן הנעשית בתחילה היא הנחשבת קן החובה, והשניה היא קן נדרה. וכיון שאין יודעים אם קן נדרה, שהקריב ממנו בטעות אחד למטה, ונפסל, היתה של תורים או של בני יונה — עליה להביא מספק שני גוזלות, תור ובן יונה, לעולה.","אם בזמן שנדרה \u0003פרשה נדרה,\u0004 שאמרה במפורש מהו המין ממנו תביא לנדרה, שני תורים או שני בני יונה. ואינה זוכרת עתה מה נדרה, והביאה את שתי קיניה ממין אחד, והכהן הקריב שני גוזלות למעלה ושניים למטה — הריהי \u0003[צריכה] להביא עוד שלש פרידין\u0004 לעולת העוף: גוזל אחד מאותו מין שהביאה (במקום הגוזל שנפסל), ושני גוזלות מהמין שלא הביאה (מספק, אולי ממין זה נדרה).","וכאמור, דין זה נאמר כאשר הביאה האשה את שתי קיניה, החובה והנדר, \u0003ממין אחד. ו\u0004אולם אם הביאה את שתי קיניה \u0003משני מינין,\u0004 קן אחת ובו שני בני יונה, וקן אחת ובו שני תורים, ומכל קן הוקרב גוזל אחד למעלה וגוזל אחד למטה, ואין הכהן זוכר איזו קן הוקרבה תחילה (לשם חובה) ואיזו שניה (לשם נדרה) — \u0003תביא ארבע\u0004 גוזלות לעולה: תור ובן יונה — מספק איזה מין היה הגוזל השני שנעשה למטה ונפסל, ועוד תור ובן יונה — להשלים כל אחד מהם לקן שלם, שהרי אינה זוכרת מאיזה מין נדרה.","ואם \u0003קבעה\u0004 שתביא קן \u0003נדרה\u0004 יחד עם עולת חובתה, שלוש עולות כאחת, וגם פירשה מאיזה מין תביא נדרה, ושכחה מאיזה מין נדרה."],["\u0003צריכה שתביא עוד חמש פרידין למעלה\u0004 (לעולה). שכיון שנדרה להביא את קן הנדבה יחד עם עולת החובה, שלוש עולות כאחת, ולא הוקרבו אלא שתי עולות, הרי גם אם הביאה ממין שנדרה — לא נתקיים נדרה. וכיון שאינה יודעת מאיזה מין נדרה, הריהי חייבת להביא שני בני יונה ושני תורים, יחד עם גוזל לחובתה ממין שהקריבה את חטאתה למטה.","כל זה אמור כשהביאה את שתי הקינים \u0003ממין אחד, ו\u0004אולם אם הביאה את שתי הקינים \u0003משני מינין,\u0004 ואינה יודעת מאיזה מין קרבה חובתה \u0003—\u0004 \u0003תביא שש\u0004 פרידות למעלה לעולה: שני תורים ושני בני יונה מספק מה נדרה, יחד עם תור ובן יונה לקן חובתה. כיון שצריכה עולת העוף של קן החובה להיות מאותו המין של חטאת העוף, ואינה יודעת מה היה.","אם פירשה את נדרה ושכחה את מינו, ו\u0003נתנתן לכהן\u0004 את שתי הקינים לחובתה ולנדרה, \u0003ואינה יודעת מה נתנה,\u0004 האם היו אלה שני קיני תורים, או שני קיני בני יונה, או קן בני יונה וקן תורים. ו\u0003הלך הכהן ועשה, ואינו יודע מה עשה,\u0004 האם עשה את שתי הקינים הללו למטה, או את שתיהן למעלה, או חציין למטה וחציין למעלה, ויתכן איפוא שלא יצאה ידי חובתה ולא ידי נדרה — \u0003צריכה\u0004 האשה להביא שבעה גוזלות, שהם: \u0003ארבע פרידין\u0004 (שני בני יונה ושני תורים) — \u0003לנדרה,\u0004 שהרי אינה יודעת מה נדרה. \u0003ושתים\u0004 (בן יונה ותור) — \u0003ל\u0004עולת \u0003חובתה,\u0004 אולי נעשו שתי הקינים הראשונות למטה. והרי עולת החובה צריכה לבוא מאותו המין של חטאת החובה, ואינה יודעת איזה מין קרב תחילה לחובתה. \u0003וחטאת אחת,\u0004 שמא נעשו שתי הקינים הראשונות למעלה, ולא קרבה החטאת עדיין. ותביא לשם כך תור או בן יונה.","\u0003בן עזאי אומר:\u0004 צריכה להביא מספק \u0003שתי חטאות,\u0004 בן יונה ותור, שלדעתו, צריך להביא חטאתה מאותו מין שקרבה עולת חובתה, ואינו יודע אם היה זה תור או בן יונה.","\u0003אמר ר' יהושע\u0004 כמשל לדבר: \u0003זהו שאמרו\u0004 על הכבש הזה, \u0003כשהוא חי\u0004 — \u0003קולו אחד, וכשהוא מת\u0004 — \u0003קולו שבעה:\u0004 שתי קרניו — שתי חצוצרות, שתי שוקיו — שני חלילים, עורו — עור תוף, מעיו העבים — מיתרי נבלים, ובני מעיו הדקים — מיתרי כינורות. ואף יולדת זו, שבאה לידי ספק, סופה שמביאה שבעה קרבנות יתירים. ומגיעים עתה לסיכום השאלה: מכלל שסיכם ר' יהושע את האמור במסכת קינים, יש להסיק כי מסכת זו היא כשיטתו. ומכאן קושיה על הסברו של רב אדא בר אהבה לשיטת ר' יהושע שבמשנתנו, שעולת העוף שנעשתה למטה כחטאת העוף הריהי נמשכת ונעשית חטאת, ומשום כך אין בה מעילה. שהרי שנינו במשניות אלה שהיא נפסלת בכך!","ומשיבים: \u0003אימר\u0004 \u0005[אמור]\u0006 ש\u0003אמר ר' יהושע\u0004 את שיטתו זו כהסבר מדוע יש \u0003לאפוקה\u0004 \u0005[להוציא אותה\u0006 את עולת העוף שנעשתה כחטאת\u0005]\u0006 \u0003מידי\u0004 דין \u0003מעילה\u0004 כחטאת, ואולם \u0003למיסק ליה\u0004 \u0005[להעלות אותה,\u0006 שתיחשב כחטאת כשירה לגמרי\u0005]\u0006 \u0003ל\u0004צאת בה ידי \u0003חובה מי\u0004 \u0005[האם]\u0006 \u0003אמר?!\u0004","\u0003כל הפסולין\u0004 לעבודה \u0003שמלקו\u0004 עוף קדשים — \u0003מליקתן פסולה, ו\u0004אף על פי כן בשרן \u0003אינו מטמא\u0004 כשהוא מצוי \u0003בבית הבליעה\u0004 כנבלת העוף. \u0003מלק\u0004 הכהן את קרבן העוף שלא בידו הימנית, אלא \u0003בשמאל, או\u0004 שמלק לא ביום אלא \u0003בלילה,\u0004 או ש\u0003שחט\u0004 עוף של \u0003חולין בפנים\u0004 (בעזרה שבמקדש), \u0003ו\u0004כן אם שחט עוף של \u0003קדשים בחוץ\u0004 לעזרה, בכל המקרים הללו, אף שנאסרו העופות באכילה — \u0003אינן מטמאות בבית הבליעה,\u0004 שהמליקה היא כשחיטה ומוציאה מדין נבילה.","ואולם אם \u0003מלק\u0004 שלא בציפורן האגודל, אלא \u0003בסכין,\u0004 וכן אם \u0003מלק חולין בפנים, וקדשים בחוץ,\u0004"],["\u0003תורין\u0004 צעירים \u0003ש\u0004עדיין \u0003לא הגיע זמנן\u0004 להיות ראויים להקרבה, או גוזלים \u0003בני יונה ש\u0004כבר בגרו ו\u0003עבר זמנן,\u0004 או מלק גוזל \u0003שיבשה גפה\u0004 (כנפה) או \u0003שנסמית\u0004 (שנתעוורה) \u0003עינה, ו\u0004כן גוזל \u0003שנקטעה רגלה\u0004 — כל אלו, אף שנמלקו, כזית מנבלתם \u0003מטמא בבית הבליעה.\u0004","\u0003זה הכלל\u0004 בענין זה: \u0003כל\u0004 עוף \u0003ש\u0004היה כשר מתחילה, והיה \u0003פסולו בקודש\u0004 בתוך כדי עבודה — \u0003אינו מטמא בבית הבליעה.\u0004 וכל עוף ש\u0003לא היה פסולו בקודש\u0004 שנפסל קודם עבודת ההקרבה — \u0003מטמא בבית הבליעה.\u0004","ומביאים מחלוקת בענין מליקת זר, שלא שנינו במפורש במשנתנו. \u0003אמר רב:\u0004 מליקת \u0003שמאל ולילה\u0004 — \u0003אין מטמאין בבית הבליעה\u0004 כדין נבלת העוף. אבל מליקה שנעשתה על ידי \u0003זר\u0004 (מי שאינו כהן) \u0003ו\u0004כן מליקה שנעשתה לא בצפורן האגודל, אלא ב\u0003סכין\u0004 — \u0003מטמאין בבית הבליעה.\u0004","ושואלים על שיטה זו: \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה,\u0006 מיוחד\u0005]\u0006 דינה של מליקה ביד \u0003שמאל,\u0004 שאין העוף מטמא למרות שמליקה פסולה היא — משום \u0003דאית ליה הכשירה\u0004 \u0005[שיש לו\u0006 לנעשה ביד שמאל מקרה אחר של \u0005הכשר],\u0006 והוא בסדר העבודה ש\u0003ביום הכפורים\u0004 (בהכנסת כף הקטורת לקודש הקדשים, שהיא נעשית בשמאל). \u0003ו\u0004גם טעמה של מליקה ב\u0003לילה\u0004 שאינה מטמאה, הריהו משום ש\u0003אית ליה הכשירה\u0004 \u0005[שיש לו\u0006 מקרה אחר של \u0005הכשר],\u0006 והוא \u0003ב\u0004הקטרת \u0003איברים ופדרים\u0004 על המזבח בלילה. אם כן, \u0003זר נמי אית ליה הכשירה\u0004 \u0005[גם כן יש לו\u0006 מקרה אחר של \u0005הכשר],\u0006 והוא \u0003ב\u0004עבודת ה\u0003שחיטה\u0004 שהיא כשירה בזר, ומדוע סבור רב שמליקתו מטמאה בבית הבליעה! ומשיבים: \u0003שחיטה לאו\u0004 \u0005[לא]\u0006 \u0003עבודה היא,\u0004 ומשום כך אין בהכשר שחיטה הנעשה בזר ללמד על מליקת זר שלא תטמא, שהרי מליקה עבודה היא.","ושואלים על כך: \u0003ולא,\u0004 והאם אין שחיטה נחשבת עבודה? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' זירא: שחיטת פרה\u0004 אדומה שנעשתה \u0003בזר\u0004 — \u0003פסולה, ומחוי\u0004 \u0005[והראה,\u0006 נתן סימן\u0005]\u0006 \u0003רב עלה\u0004 \u0005[עליה,\u0006 על מקורה של הלכה זו\u0005]\u0006 ממה שהוזכר במעשה שחיטתה \u0003אלעזר\u0004 הכהן (במדבר יט, ג), \u0003ו\u0004נאמר בפרשה זו לשון \u0003\"חוקה\"\u0004 (\"זאת חוקת התורה\", במדבר יט, ב) — ללמד שהרי זה לעכב!","ומשיבים: \u0003שאני\u0004 \u0005[שונה,\u0006 מיוחד\u0005]\u0006 הוא דינה של \u0003פרה\u0004 אדומה שכן \u0003קדשי בדק הבית היא,\u0004 ולא קדשי מזבח, ואין מעשיה נחשבים כחלק מעבודת הקרבנות.","ותמהים: \u0003ולא כל\u0004 ש\u0003כן הוא?\u0004 אם \u0003קדשי בדק הבית\u0004 הקלים בדינם \u0003בעו\u0004 \u0005[צריכים]\u0006 \u0003כהונה, קדשי מזבח\u0004 החמורים בדינם \u0003מיבעיא\u0004 \u0005[צריך לומר]\u0006 שהם טעונים שחיטה על ידי כהן? ואם כן עבודה היא!","\u0003אמר רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי:\u0004 אין הדברים תלויים זה בזה, \u0003מידי דהוה\u0004 \u0005[כמו שהוא]\u0006 דין \u0003מראות נגעים\u0004 ראיית נגע הצרעת, כדי לטמאו או לטהרו, \u0003דלאו\u0004 [שלא] \u0003עבודה היא, ו\u0004בכל זאת \u0003בעיא\u0004 \u0005[צריכה]\u0006 \u0003כהונה\u0004 (ראה ויקרא יג,ב ועוד).","ושואלים עוד על רב: \u0003ונילף\u0004 \u0005[ונלמד]\u0006 \u0003מבמה\u0004 (במת יחיד, שהיו מקריבים בה קרבנות קודם שהוקם המקדש) שזר כשר למלוק שם עופות, ואם כן יש צד של הכשר במליקת זר, ותהא משום כך מליקת זר בעזרה מוציאתו מטומאת נבילה!","ומתרצים: \u0003מ\u0004דינים הנוהגים ב\u0003במה לא יליף\u0004 \u0005[אין למדים]\u0006 לדינים הנוהגים במקדש, שכן הבמה נחשבת כחול ביחס למקדש.","ושואלים על כך: \u0003ו\u0004האם אכן \u0003לא\u0004 למדים מבמה? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003מנין ל\u0004קרבן ש\u0003יוצא\u0004 מהעזרה ונפסל בכך, \u0003שאם\u0004 בכל זאת \u0003עלה\u0004 על המזבח דינו ש\u0003לא ירד\u0004 מן המזבח, ויוקרב \u0003—\u0004 \u0003שהרי\u0004 הקרבן ה\u0003יוצא כשר בבמה\u0004 שאין בה תחום מסויים להקרבה!","ומתרצים: ה\u0003תנא\u0004 על הכתוב \u0003\"זאת תורת העולה\"\u0004 (ויקרא ו, ב) \u0003סמיך ליה\u0004 \u0005[סמך לו\u0006 למד\u0005],\u0006 עיקר לימודו היה ממקרא זה, המלמד שכל שעלה למזבח לא ירד, ובכלל זה יוצא. ולא הוזכרה הבמה אלא כאסמכתא בלבד, שכן אין למדים מבמה. עד כאן דנו בשיטת רב שמליקת זר, כמו מליקת סכין, עושה את העוף נבילה.","\u0003ו\u0004אילו \u0003ר' יוחנן אמר:\u0004 במליקת \u0003זר\u0004 — \u0003אין\u0004 העוף \u0003מטמא\u0004 ב\u0003בית הבליעה,\u0004 במליקת \u0003סכין\u0004 — \u0003מטמא\u0004 העוף ב\u0003בית הבליעה.\u0004","ומביאים ראייה, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003כל הפסולין שמלקו\u0004 — \u0003מליקתן פסולה\u0004 ואינן מטמאות בבית הבליעה. \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003לר' יוחנן\u0004 — המלה \u0003\"כל\"\u0004 באה \u0003לאיתויי\u0004 \u0005[להביא,\u0006 לרבות\u0005]\u0006 \u0003זר,\u0004 שאף מליקתו פסולה ואינה מטמאה בבית הבליעה. \u0003אלא לרב\u0004 שאינו סבור כן, \u0003\"כל\" לאיתויי מאי\u0004 \u0005[להביא,\u0006 לרבות \u0005מה],\u0006","\u0003(לאו) לאיתויי\u0004 \u0005[להביא]\u0006 מליקה ב\u0003שמאל ו\u0004מליקה ב\u0003לילה?\u0004 והרי מליקת \u0003שמאל ולילה בהדיא קתני\u0004 \u0005[במפורש שנינו\u0006 במשנה את דינן\u0005],\u0006 ואין צורך להשמיע את דינם בדרך ריבוי מהמלה \"כל\"! ומתרצים: לדעת רב, \u0003תני\u0004 \u0005[שונה\u0006 התנא\u0005]\u0006 במשנה בלשון כוללת, \u0003והדר\u0004 \u0005[וחוזר]\u0006 ו\u0003מפרש\u0004 את הדין.","ומביאים עוד ראייה, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו בהמשך המשנה: \u0003זה הכלל, כל\u0004 עוף \u0003שהיה פסולו בקודש\u0004 — \u0003אינו מטמא\u0004 את האוכלו, לטמא \u0003בגדים\u0004 שעליו בעת שכזית מן העוף נתון ב\u0003בית הבליעה\u0004 שלו. \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003ר' יוחנן\u0004 — הלשון \u0003\"כל\"\u0004 באה \u0003לאיתויי\u0004 \u0005[להביא,\u0006 לרבות\u0005]\u0006 מליקת \u0003זר,\u0004 לומר שאינה מטמאת בבית הבליעה. \u0003אלא ל\u0004שיטת \u0003רב,\u0004 שמליקת זר מטמא בבית הבליעה — הלשון \"כל\" \u0003לאיתויי מאי\u0004 \u0005[לרבות\u0006 את \u0005מה\u0006 היא באה\u0005]?\u0006"],["ודוחים: \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 הבאה להוכיח מכלל זה שבמשנה כדעת ר' יוחנן, הכלל ששנינו לעומתו: \"כל \u0003שלא היה פסולו בקודש\u0004 מטמא בבית הבליעה\" \u0003לאיתויי מאי\u0004 \u0005[להביא,\u0006 לרבות \u0005מה]\u0006 הוא בא, לדעת ר' יוחנן? מליקה של איזה מן הפסולים?","\u0003אלא\u0004 כללים אלו באו לרבות פסולים אחרים שלא נשנו במפורש במשנה: \u0003רישא\u0004 \u0005[\u0006הכלל ש\u0005בתחילה]\u0006 \"כל שפסולו בקודש\" — \u0003לאיתויי\u0004 \u0005[\u0006\u0005להביא,\u0006 להוסיף\u0005]\u0006 \u0003שחיטת\u0004 עוף \u0003קדשים בפנים,\u0004 שאף היא אינה מטמאה בבית הבליעה. ואילו \u0003סיפא\u0004 \u0005[\u0006הכלל ש\u0005בסוף]\u0006 \"כל שלא היה פסולו בקודש\" — \u0003לאיתויי\u0004 \u0005[להביא,\u0006 להוסיף\u0005]\u0006 \u0003מליקת חולין בחוץ,\u0004 שהיא מטמאה בבית הבליעה.","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כמותו,\u0006 כשיטתו\u0005]\u0006 של \u0003ר' יוחנן: מלקה זר,\u0004 וכן אם \u0003מלקה\u0004 כהן ה\u0003פסול\u0004 לעבודה, וכן \u0003הפיגול\u0004 עוף שנעשה במחשבת חוץ לזמנו, \u0003והנותר\u0004 מבשר העוף למחר, \u0003והטמא\u0004 בשר העוף שנטמא — אף שאסורים באכילה ובהקרבה, \u0003אין מטמאין\u0004 ב\u0003בית הבליעה.\u0004","\u0003אמר ר' יצחק: שמעתי שתים\u0004 הלכות, \u0003אחת\u0004 בענין \u0003קמיצת זר\u0004 שקמץ הזר את הקומץ מן המנחה להקטירו, \u0003ואחת\u0004 בענין \u0003מליקת זר,\u0004 שאף ששתיהן פסולות, \u0003אחת\u0004 אם עלתה למזבח \u0003תרד,\u0004 \u0003ואחת\u0004 \u0003לא תרד, ו\u0004אולם \u0003לא ידענא\u0004 \u0005[איני יודע]\u0006 באיזו מהן נאמרה הלכה זו ובאיזו נאמרה הלכה זו. \u0003אמר חזקיה: מסתברא\u0004 \u0005[מסתבר]\u0006 לומר ש\u0003קמיצה\u0004 שנעשתה על ידי זר — \u0003תרד,\u0004 ואילו \u0003מליקה\u0004 שנעשתה על ידי זר — \u0003לא תרד.\u0004","ושואלים: \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 \u0003מליקה\u0004 שנעשתה על ידי זר שלא תרד, שכן \u0003ישנה בבמה,\u0004 כשלא היה משכן או מקדש, שאין שם צורך בכהן, אם כן \u0003קמיצה\u0004 בזר \u0003נמי\u0004 \u0005[גם כן]\u0006 לא תרד, שכן \u0003ישנה בבמה!\u0004","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שאין קמיצה בבמה משום ש\u0003אין מנחה\u0004 נוהגת \u0003בבמה\u0004 — הרי לשיטה זו \u0003אין\u0004 הקרבת \u0003עופות נמי\u0004 \u0005[גם כן]\u0006 נוהגת \u0003בבמה,\u0004 ואין איפוא מליקה בבמה!","שכן \u0003אמר רב ששת: לדברי האומר יש מנחה בבמה\u0004 — \u0003יש עופות בבמה, לדברי האומר אין מנחה\u0004 בבמה — \u0003אין עופות\u0004 בבמה, \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 שכך נאמר בענין הקרבנות שהוקרבו בהר סיני (קודם שהוקם המשכן): \"ויעלו עולות ויזבחו זבחים שלמים לה' פרים\" (שמות כד, ה), והלשון \"זבחים\" יש בה הדגשה כפולה: \u0003\"זבחים\"\u0004 — \u0003ולא מנחות, \"זבחים\"\u0004 — \u0003ולא עופות!\u0004","\u0003אלא אימא\u0004 \u0005[אמור]\u0006 שאף שנהגו גם מליקה וגם קמיצה בבמה, ממליקה בבמה יש ללמוד לענין מליקה במקדש, ואולם מקמיצה בבמה אין ללמוד קמיצה במקדש, ששני עניינים שונים הם, שהרי \u0003אין קידוש בכלי שרת במנחה בבמה\u0004 שאין צורך להניח את קומץ המנחה בכלי שרת לקדשו, ואילו במקדש חובה לעשות כן.","שנינו במשנה שאם \u0003מלק בשמאל או בלילה\u0004 אינן מטמאות בבית הבליעה. ועוד בענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003יכול תהא מליקה\u0004 פסולה, כגון שנעשתה בשמאל, או בלילה, \u0003שהיא לפנים\u0004 (במקדש) \u0003מטמאה בגדים בבית הבליעה\u0004 כדין נבלת העוף? \u0003תלמוד לומר\u0004 בענין נבלת העוף: \"וכל נפש אשר תאכל \u0003נבלה\u0004 וטרפה... וטמא עד הערב\" (ויקרא יז, טו), וזו שנמלקה בשמאל או בלילה אין היא בכלל \"נבילה\", ואינה מטמאה.","ותמהים: ומדוע לא נאמר ש\u0003הא נמי\u0004 \u0005[זו גם כן]\u0006 \u0003נבלה היא,\u0004 ותטמא בבית הבליעה! \u0003אלא\u0004 יש להבין כך: \u0003תלמוד לומר\u0004 \"נבילה ו\u0003טריפה\"\u0004 (ויקרא יז, טו), וטריפה הוזכרה כאן כדי ללמדנו במי נוהגת טומאת נבילה: \u0003מה טריפה\u0004 הריהי דבר \u0003שאין מתרת את האיסור,\u0004 שאין עצם היטרפות העוף מתיר כל איסור שיש בו, \u0003אף כל\u0004 דרך המתה של העוף \u0003שאין\u0004 \u0003מתרת את האיסור\u0004 הריהי בכלל טומאת נבילה.","\u0003יצא\u0004 מכלל זה כל \u0003מליקה שהיא\u0004 נעשית \u0003לפנים\u0004 (במקדש), ואפילו זו שנעשתה בידי הפסול לעבודה או בלילה, ש\u0003הואיל והיא מתרת את האיסור,\u0004 שהרי אם עלתה לא תרד, וקודם המליקה לא היתה ראויה לכך — \u0003אין מטמא בגדים בבית הבליעה.\u0004","\u0003הביא\u0004 (נכנס בכלל זה) של המטמאים בבית הבליעה \u0003המולק (ק\"ץ חפ\"ץ = ק\u0004 דשים בחו \u0003ץ, ח\u0004 ולין ב\u0003פ\u0004 נים ובחו \u0003ץ. סימן\u0004 לדינים הבאים\u0003) קדשים בחוץ, ומולק חולין בין מבפנים בין מבחוץ, הואיל ואין מתירין את האיסור,\u0004 שהרי אף עתה אסורים הם בהקרבה — \u0003מטמאין בגדים\u0004 ב\u0003בית הבליעה.\u0004","ועוד בענין טומאת בית הבליעה \u0003תניא אידך\u0004 \u0005[שנויה ברייתא\u0006 אחרת\u0005]:\u0006 \u0003יכול תהא שחיטת\u0004 עוף של \u0003חולין לפנים\u0004 (במקדש), \u0003ו\u0004שחיטת עוף של \u0003קדשים, בין מבפנים ובין מבחוץ\u0004 — \u0003מטמאה\u0004 ב\u0003בית הבליעה? תלמוד לומר\u0004 בדינה של טומאה זו: \u0003\"נבלה\"\u0004 (ויקרא יז, טו), ואלו שנשחטו אין הם בכלל \"נבילה\" שתטמא.","ותמהים: ובאמת, מדוע לא נאמר ש\u0003הא\u0004 \u0005[\u0006שחיטה \u0005זו]\u0006 שנעשתה שלא כהלכתה \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003נבלה היא! אלא תלמוד לומר:\u0004 \"נבילה ו\u0003טריפה\"\u0004 (ויקרא יז, טו), והזכרת טריפה בפסוק זה באה ללמדנו במי נוהגת טומאת בית הבליעה: \u0003מה טריפה\u0004 הריהי \u0003שווה\u0004 באיסורה \u0003בפנים כבחוץ,\u0004 שכאן וכאן היא אסורה, \u0003אף כל\u0004 שהן \u0003שוות\u0004 לאיסורן \u0003בפנים כבחוץ\u0004 הריהן בכלל המטמאות בבית הבליעה.","\u0003יצא\u0004 מכלל זה \u0003שחיטת חולין בפנים, ו\u0004כן שחיטת \u0003קדשים בין מבפנים בין מבחוץ, הואיל ולא שוו\u0004 לאיסור \u0003בפנים כבחוץ\u0004 — \u0003אין מטמאין בגדים אבית הבליעה.\u0004","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003חולין לא שוו בפנים כבחוץ,\u0004 שהרי עופות חולין שנשחטו בחוץ כדינם — בוודאי כשרים, ואילו חולין שנשחטו בפנים — אסורים, \u0003אלא\u0004 שחיטת עוף \u0003קדשים,\u0004 הרי \u0003אידי ואידי\u0004 \u0005[אלו ואלו,\u0006 בחוץ ובפנים\u0005]\u0006 \u0003פסולין נינהו\u0004 \u0005[הם]!\u0006","\u0003אמר רבא:\u0004 שחיטת עוף קדשים בחוץ אינה נלמדת מכתוב זה, אלא סברה היא: \u0003אם הועילה\u0004 (נחשבת) \u0003לו\u0004 לעוף \u0003שחיטת חוץ\u0004 כשחיטה כשירה, עד כדי \u0003לחייבו כרת\u0004 עליה משום שחיטת חוץ (ראה להלן זבחים קז,א), \u0003לא תועיל\u0004 (תיחשב) \u0003לו\u0004 לשחיטה כשירה כדי \u0003לטהרה\u0004 בכך \u0003מידי\u0004 טומאת \u0003נבילה?\u0004","ולפי זה, כך יש להבין את הברייתא: \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 ששחיטת קדשים ב\u0003חוץ\u0004 אינה מטמאה, ואולם שחיטת קדשים ב\u0003פנים מנלן\u0004 \u0005[מנין לנו]\u0006 שאינה מטמאה? ועל כך משיבה הברייתא — \u0003הואיל ולא שוו\u0004 שחיטת קדשים \u0003בפנים כבחוץ,\u0004 שהרי כפי שלמדנו מסברה, שחיטת קדשים בחוץ שחיטה כשירה היא (לחייבו כרת) ואינה מטמאה, וכלל הוא שכל שלא שוו בחוץ ובפנים אינם מטמאים.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003מלק קדשים בחוץ נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 יטמאו, שהרי \u0003לא שוו\u0004 \u0005[שוים]\u0006 באיסורם \u0003בפנים כבחוץ,\u0004 שמליקה בפנים כשירה היא. אבל במשנה שנינו שהם מטמאים!","\u0003אמר רב שימי בר אשי: דנין\u0004 לטהר \u0003דבר\u0004 שנעשה \u0003שלא בהיכשרו\u0004 (שחיטת עוף קדשים בפנים) \u0003מדבר\u0004 שנעשה \u0003שלא בהיכשרו\u0004 (שחיטת עוף קדשים בחוץ), \u0003ואין דנין\u0004 לטהר \u0003דבר\u0004 שנעשה \u0003שלא בהיכשרו\u0004 (מליקת קדשים בחוץ) \u0003מדבר ש\u0004נעשה \u0003בהיכשרו\u0004 (מליקת קדשים בפנים), שהרי יש לומר כי דווקא משום שנעשה הדבר בהכשרו אינו מטמא.","ושואלים על כלל זה: \u0003ו\u0004האם אכן \u0003לא\u0004 למדים דבר שלא בהכשרו מדבר שבהכשרו? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003מנין ל\u0004בשר הקרבן ש\u0003יוצא\u0004 מהעזרה ונפסל בכך, \u0003שאם\u0004 בכל זאת \u0003עלה\u0004 על המזבח דינו ש\u0003לא ירד\u0004 מן המזבח — \u0003שהרי\u0004 ה\u0003יוצא כשר בבמה,\u0004 שאין שם תחום מסויים להקרבה. ואם כן, למדים להכשיר דבר שנעשה שלא כראוי (במקדש) מדבר שנעשה כמצוותו (יוצא בבמה)!","ומתרצים: ה\u0003תנא\u0004 המכשיר את היוצא, באמת אינו לומד דין זה מבמה, אלא על הכתוב \u0003\"זאת תורת העולה\"\u0004 (ויקרא ו, ב) ש\u0003ריבה\u0004 (הוסיף) הכתוב בלשון כוללת זו, שכל העולה על המזבח לא ירד, \u0003סמיך ליה\u0004 \u0005[סמך לו,\u0006 למד\u0005],\u0006 עיקר לימודו היה ממקרא זה. ואין הראיה מבמה אלא כאסמכתא בלבד.","\u0003מלק\u0004 הכהן את העוף כראוי, \u0003ו\u0004לאחר מכן \u0003נמצאת\u0004 שהיא \u0003טריפה,\u0004 שיש בעוף מכה או מחלה שהוא עתיד למות ממנה, והריהו פסול להקרבה ואסור באכילה לכהנים, \u0003ר' מאיר אומר:\u0004 כזית ממנו \u0003אינו מטמא בבית הבליעה\u0004 כשאר נבלת העוף, שכן המליקה הוציאתו מכלל נבילה."],["\u0003ר' יהודה אומר:\u0004 הריהו כשאר נבלת העוף, וכזית ממנו \u0003מטמא\u0004 בבית הבליעה.","\u0003אמר ר' מאיר\u0004 בטעם שיטתו, \u0003קל וחומר\u0004 הוא: ומה \u0003אם נבלת בהמה\u0004 שחמור דינה, \u0003ש\u0004הרי היא \u0003מטמאה במגע ובמשא\u0004 כלומר, את הנוגע בה ואת הנושא אותה (ויקרא יא, לט— מ), \u0003שחיטתה מטהרת\u0004 את \u0003טריפתה מטומאתה,\u0004 שאם נמצא לאחר השחיטה שהיא טריפה — אינה מטמאה טומאת נבילה, \u0003נבלת העוף\u0004 שקל דינה, \u0003ש\u0004הרי כזית ממנה \u0003אינו מטמא במגע ובמשא\u0004 — אלא רק כשהוא מצוי בבית הבליעה, \u0003אינו דין שתהא שחיטתו מטהרת\u0004 את \u0003טריפתו מטומאתו?\u0004","ומעתה, לאחר שלמדנו שהשחיטה מטהרת את עוף הטריפה, יש ללמוד כך: \u0003מה מצינו\u0004 (כשם שמצאנו) \u0003בשחיטתו\u0004 \u0003שהיא מכשרתה לאכילה ומטהרת\u0004 את \u0003טריפתו מטומאתו\u0004 — \u0003אף מליקתו שהיא מכשרתו באכילה\u0004 של קדשים נאמר כן, ש\u0003תטהר טריפתו מידי טומאתו.\u0004","ואילו \u0003ר' יוסי אומר:\u0004 אף שיש ללמוד מבהמה ששחיטה מטהרת את העוף מטומאתו, מכל מקום יש לדון על כך ככל דבר הנלמד מחבירו בקל וחומר, ולומר: \u0003דיה\u0004 לטריפת העוף שיהא דינה \u0003כ\u0004דין \u0003נבלת בהמה\u0004 טריפה, ולכן \u0003שחיטתה מטהרתה\u0004 מלטמא, \u0003ולא מליקתה.\u0004","שנינו במשנתנו שר' יוסי השיב על לימודו של ר' מאיר בטענת \"דיו לבא מן הדין להיות כנדון\", שבלימוד בדרך קל וחומר אין מחמירים על הלמד יותר מן המלמד. ושואלים: \u0003ו\u0004האם \u0003ר' מאיר לא דריש\u0004 \u0005[אינו דורש]\u0006 אין הוא מסייג דרשת קל וחומר בטענת \u0003\"דיו\u0004 לבא מן הדין להיות כנדון\"? \u0003והא\u0004 \u0005[והרי]\u0006 כלל זה של \u0003\"דיו\" דאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003הוא!\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 בביאור המדות שהתורה נדרשת בהן: מה ששנינו שהתורה נדרשת \u0003מדין קל וחומר, כיצד\u0004 (מנין לנו)? שכן נאמר במרים אחות משה, לאחר שננזפה על ידי ה' ונצטרעה: \u0003\"ויאמר ה' אל משה ואביה ירק ירק בפניה\u0004 הלא תכלם שבעת ימים, תסגר שבעת ימים מחוץ למחנה\" (במדבר יב, יד). כלומר, אם אביה היה גוער בה דינה בנידוי שבעה ימים — קל וחומר כשגער בה הקב\"ה. ויש לתמוה: אם בדרך \u0003קל וחומר,\u0004 הנזופה \u0003לשכינה\u0004 ראוי לה להיות מורחקת \u0003ארבעה עשר יום! אלא דיו לבא מן הדין\u0004 (הנזוף על ידי השכינה) \u0003להיות כנדון\u0004 (הנזוף על ידי אביו).","\u0003אמר ר' יוסי בר' אבין\u0004 בתשובה: אף ש\u0003ר' מאיר\u0004 דורש מידה זו של \"דיו\", והיה מקום לומר כן אף בהלכה זו של מליקת עוף טריפה, מכל מקום \u0003קרא אשכח וקדרש\u0004 \u0005[מקרא\u0006 אחר \u0005מצא ודרש],\u0006 שכן נאמר בסוף פרשת טומאת נבילות:","\u0003\"זאת תורת הבהמה והעוף\"\u0004 (ויקרא יא, מו), ומשמע: תורה אחת לשניהם. ויש לדון בדבר: \u0003וכי באיזו תורה שוותה\u0004 נבלת \u0003בהמה ל\u0004נבלת \u0003עוף ו\u0004נבלת \u0003עוף ל\u0004נבלת \u0003בהמה?\u0004 והלא דינם שונה זה מזה, שכן נבלת \u0003בהמה מטמא במגע ובמשא,\u0004 ואילו נבלת \u0003עוף אינו מטמא במגע ובמשא!\u0004 ומן הצד האחר, נבלת \u0003עוף מטמא בגדים\u0004 בהיות כזית ממנה ב\u0003בית הבליעה,\u0004 ואילו נבלת \u0003בהמה אינה מטמאה בגדים\u0004 כשהיא ב\u0003בית הבליעה!\u0004","לא באה השוואה זו \u0003אלא לומר לך\u0004 כלל זה: \u0003מה בהמה\u0004 — \u0003דבר שמכשירה לאכילה\u0004 (שחיטתה) \u0003מטהר טריפתה מטומאתה,\u0004 \u0003אף עוף, דבר שמכשיר\u0004 אותו \u0003באכילה\u0004 (שחיטה ומליקה) \u0003מטהר\u0004 את \u0003טריפתו מטומאתו.\u0004","ושואלים: \u0003ור' יהודה מאי טעמא\u0004 \u0005[מה טעם,\u0006 מאין למד\u0005]\u0006 ששחיטה אינה מוציאה עוף טריפה מידי טומאת בית הבליעה? ומשיבים: \u0003קרא אשכח וקדרש\u0004 \u0005[מקרא מצא ודרש],\u0006 שכן נאמר בדין טומאת בית הבליעה בנבלת העוף: \"וכל נפש אשר תאכל \u0003נבלה\u0004 ו\u0003טריפה...\u0004 וטמא עד הערב\" (ויקרא יז, טו), ועל כך \u0003אמר ר' יהודה: \"טרפה\" למה נאמרה\u0004 במקרא זה? שכן \u0003אם\u0004 מדובר באוכל \u0003טריפה\u0004 בזמן שהיא עדיין \u0003חיה\u0004 — \u0003הרי \"נבילה\" אמורה\u0004 בטומאת בית הבליעה, כלומר, דווקא זו שכבר מתה. ו\u0003אם\u0004 מדובר באוכל כזית מן ה\u0003טריפה\u0004 ש\u0003אינה חיה\u0004 (לאחר שמתה) — \u0003הרי היא בכלל \"נבילה\"\u0004 האמורה כבר! \u0003אלא\u0004 לא נאמר \"טריפה\" אלא \u0003להביא\u0004 (לרבות) את האוכל כזית מן ה\u0003טריפה ששחטה\u0004 קודם שמתה, \u0003ש\u0004אף היא \u0003מטמאה\u0004 כנבילה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב שיזבי: אלא מעתה,\u0004 להסבר זה, יש לדון במה \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 באיסור \u0003חלב של בהמה: \"וחלב\u0004 \u0003נבלה\u0004 וחלב \u0003טריפה\u0004 יעשה לכל מלאכה\" (ויקרא ז, כד), ומשם למדו כי חלב נבילה אינו טמא כבשרה —","\u0003התם נמי נימא\u0004 \u0005[שם גם כן נאמר]\u0006 כדרך שדן ר' יהודה, ובאופן זה: \"חלב טריפה\" למה נאמר? \u0003אם\u0004 מדובר ב\u0003טריפה\u0004 בזמן שהיא עדיין \u0003חיה\u0004 — \u0003הרי\u0004 \u0003\"נבילה\" אמורה,\u0004 שחלבה טהור למרות שבשרה טמא, וכל שכן שיהא הדין כן בחלב טריפה חיה, שבשרה עצמו טהור. ו\u0003אם\u0004 מדובר בחלב \u0003טריפה\u0004 ש\u0003אינה חיה\u0004 (לאחר שמתה) — \u0003הרי היא בכלל \"נבילה\"\u0004 האמורה כבר, שחלבה טהור! \u0003אלא\u0004 לא נאמר \"טריפה\" אלא \u0003להביא\u0004 (לרבות) \u0003טריפה ששחטה,\u0004 להשמיענו \u0003שחלבה טהור.\u0004 אלא ש\u0003מכלל\u0004 זה משמע כי אנו מניחים ש\u0003היא\u0004 עצמה, בשרה של הטריפה שנשחטה, \u0003מטמאה,\u0004 ולכן יש צורך לחדש שחלבה טהור. וכי יכול אתה לומר כן?","\u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב יהודה אמר רב, ואמרי לה במתניתא תנא\u0004 \u0005[ו\u0006יש \u0005אומרים\u0006 ש\u0005בברייתא שנה\u0006 כך\u0005]\u0006 על הנאמר בטומאת נבילה: \u0003\"וכי ימות מן הבהמה\u0004 אשר היא לכם לאכלה הנוגע בנבלתה יטמא עד הערב\" (ויקרא יא, לט). ולשון \"מן הבהמה\" מורה שלא כל הבהמות בכלל טומאה זו, \u0003מקצת בהמה מטמאה,\u0004 ו\u0003מקצת בהמה אינה מטמאה. ואיזו זו\u0004 שאינה מטמאה — \u0003זו טריפה ששחטה!\u0004","\u0003אלא,\u0004 בהכרח, לשון \u0003\"טרפה\"\u0004 האמור בטהרת חלב נבילה, לא באה לרבות חלב טריפה שנשחטה, אלא \u0003מיבעי ליה למעוטי\u0004 \u0005[הוצרך לו למעט]\u0006 בהמה \u0003טמאה,\u0004 לומר שאין חלבה טהור, כי לשון \"טריפה\" באה ללמד שבכלל כתוב זה רק \u0003מי שיש במינה\u0004 איסור \u0003טריפה,\u0004 שהיא הבהמה הטהורה. \u0003יצתה\u0004 (יצאה) \u0003זו,\u0004 הבהמה הטמאה, \u0003שאין במינה\u0004 איסור \u0003טריפה,\u0004 שהרי ממילא היא אסורה.","אם כן, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 לענין טומאת נבלת העוף, נאמר כי לשון \"טריפה\" (ויקרא יז, טו) באה \u0003למעוטי\u0004 \u0005[למעט]\u0006 נבלת \u0003עוף טמא\u0004 שאינה מטמאת, \u0003ש\u0004כן \u0003אין במינו טריפה.\u0004 ולא כפי שפירשו בשם ר' יהודה, לרבות טריפת העוף ששחטה!","ומשיבים: דין נבלת \u0003עוף טמא\u0004 שאינה מטמאה, \u0003ל\u0004שיטת \u0003ר' יהודה מ\"נבלה\"\u0004 האמורה במקום אחר \u0003נפקא ליה\u0004 \u0005[יוצא,\u0006 נלמד \u0005לו].\u0006","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יהודה אומר: יכול תהא נבלת עוף טמא מטמאה בגדים\u0004 ב\u0003בית הבליעה? תלמוד לומר\u0004 בדין טומאת נבלת העוף: \u0003\"נבלה וטרפה לא יאכל\u0004 לטמאה בה\" (ויקרא כב, ח) — טומאה זו נוהגת ב\u0003מי שאיסורו משום בל תאכל נבילה,\u0004 שאסור לאוכלו מחמת שלא נשחט כראוי, \u0003יצא זה,\u0004 העוף הטמא, \u0003שאין איסורו משום בל תאכל נבילה, אלא משום בל תאכל טמא.\u0004 ולכן דורש ר' יהודה \"טריפה\" האמורה בתחילה (ויקרא יז, טו) לרבות טריפה ששחטה, ללמד שהיא מטמאה בבית הבליעה."],["ושואלים: אם בדרך זו הוא למד, \u0003האי נמי\u0004 \u0005[זו גם כן]\u0006 טומאת חלב נבילה של בהמה טמאה, \u0003תיפוק\u0004 \u0005[תצא,\u0006 תילמד\u0005]\u0006 \u0003לי\u0004 ממה שנאמר: \u0003\"וחלב נבלה\u0004 וחלב טריפה יעשה לכל מלאכה\" (ויקרא ז, כד), והמלים \"ואכול לא תאכלוהו\" מלמדות כי דווקא","\u0003מי שאיסורו משום בל תאכל חלב נבלה\u0004 הוא זה שאין חלבו מטמא טומאת נבילות (כנלמד מהכתוב \"יעשה לכל מלאכה\"). \u0003יצאתה זו\u0004 (בהמה טמאה) \u0003שאין איסורה משום בל תאכל [חלב נבלה], אלא משום\u0004 שהיא בעל חיים \u0003טמא,\u0004 ולכן אין חלב נבלתה מטמא. ואין צורך איפוא ללמוד הלכה זו מ\"טריפה\" האמורה בענין זה!","ומשיבים: \u0003אלא\u0004 לשיטת ר' יהודה, \u0003האי\u0004 \u0005[אותה]\u0006 \u0003\"טרפה\"\u0004 האמורה שם \u0003מיבעי לאיתויי\u0004 \u0005[הוצרכה\u0006 כדי \u0005להביא,\u0006 לרבות\u0005]\u0006 חלב \u0003חיה\u0004 טהורה שמתה, ללמד שאינו טמא. שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 דווקא \u0003מי שחלבה אסור\u0004 באכילה \u0003ובשרה מותר\u0004 באכילה (בהמה טהורה), חלבה אינו בכלל טומאת נבילות. \u0003יצאת זו\u0004 (חיה טהורה) \u0003ש\u0004הן \u0003חלבה ו\u0004הן \u0003בשרה מותר\u0004 באכילה כשנשחטה כראוי, ולכן אם נתנבלה — גם חלבה טמא. לכן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 הכתוב בלשון \"טריפה\", שכל שיש במינו טריפה — אין חלב נבלתו טמא, ואף חלב חיה טהורה בכלל זה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 בדחייה: אין אתה יכול לדרוש כך, שכן \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 חלב בהמה \u0003טמאה\u0004 שאינו בכלל האמור בפסוק זה — משום ש\u0003אין חלבה חלוק מבשרה,\u0004 שהרי שניהם אסורים באכילה. \u0003חיה נמי\u0004 \u0005[גם כן]\u0006 \u0003אין חלבה חלוק מ\u0004דינו של \u0003בשרה,\u0004 שהרי שניהם מותרים באכילה! \u0003ועוד, הכתיב\u0004 \u0005[הרי נאמר]\u0006 באותו כתוב: \u0003\"ואכל לא תאכלוהו\",\u0004 ומשם למדו כי מדובר בפסוק זה בחלב שאסור באכילה. ואילו חלב חיה טהורה מותר באכילה!","\u0003אלא אמר אביי:\u0004 לשיטת ר' יהודה, הכתוב \"וחלב \u0003טריפה\" לגופיה איצטריך\u0004 \u0005[לגופו,\u0006 לדין חלב טריפה של בהמה טהורה עצמה, \u0005הוצרך],\u0006 להשמיענו שאף הוא אינו בכלל טומאת נבילות. \u0003שלא תאמר: הואיל ו\u0004בהמה \u0003טמאה אסורה מחיים, ו\u0004כן \u0003טריפה אסורה מחיים,\u0004 אם כן יש מקום להשוותם: \u0003מה\u0004 בהמה \u0003טמאה חלבה טמא, אף טריפה חלבה טמא.\u0004","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שבדרך זו הוא דורש, \u0003האי נמי\u0004 \u0005[זו גם כן]\u0006 לשון \"טריפה\" האמורה בענין טומאת נבלת עוף (ויקרא יז, טו), שממנה למד ר' יהודה ששחיטת עוף טריפה אינה מטהרתו, \u0003מיבעי\u0004 \u0005[הוצרכה]\u0006 לגופה, ללמד שנבלת עוף טריפה מטמאה. \u0003שלא תאמר: הואיל ועוף טמא אסור באכילה, וטריפה אסורה באכילה,\u0004 יש מקום להשוותם: \u0003מה עוף טמא אינו מטמא\u0004 בטומאת בית הבליעה, \u0003אף טריפה אינה מטמאה!\u0004","\u0003ועוד, מי איכא למילף\u0004 \u0005[האם\u0006 בכלל \u0005יש\u0006 מקום \u0005ללמוד]\u0006 לגבי בהמה \u0003טרפה מ\u0004בהמה \u0003טמאה,\u0004 שלשם כך הוצרך הכתוב לשלול לימוד שכזה? והרי \u0003טמאה\u0004 חמורה יותר, ש\u0003לא היתה לה\u0004 מעולם \u0003שעת הכושר,\u0004 שמשעת לידתה אסורה היא, ואילו \u0003טריפה היתה לה שעת הכושר,\u0004 קודם שנטרפה! \u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 בהמה שהיתה \u0003טריפה\u0004 עוד \u0003מ\u0004זמן היותה ב\u0003בטן\u0004 אמה, שלא היתה לה מעולם שעת הכושר, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 הרי יש צורך בכתוב המלמד שחלבה טהור — גם לכך אין צורך, שכן \u0003במינה מיהא איכא\u0004 \u0005[על כל פנים יש]\u0006 שעת כושר!","\u0003אלא אמר רבא:\u0004 לשיטת ר' יהודה, \"טריפה\" שהובאה בענין זה לא באה ללמדנו לגבי טומאת חלב הטריפה, אלא לגבי איסור אכילתו, שבפסוק זה \"וחלב נבילה וחלב טריפה... אכול לא תאכלוהו\" \u0003התורה אמרה: יבא איסור נבילה ויחול על איסור חלב,\u0004 לחייב את האוכלו גם משום איסור חלב וגם משום איסור נבילה. וכן \u0003יבא איסור טריפה ויחול על איסור חלב,\u0004 לחייב את האוכלו משום חלב ומשום טריפה.","ומוסיפים: \u0003וצריכי\u0004 \u0005[ונצרכו]\u0006 שני המקראות להיאמר, בנבילה ובטריפה, שכן לא היינו למדים מן האחד את דינו של השני, משום \u0003דאי אשמעינן\u0004 \u0005[שאם היה משמיע לנו]\u0006 כן רק באיסור \u0003נבילה\u0004 שהוא חל על איסור חלב, היה מקום לומר כי טעם הדבר הוא — \u0003משום דמטמיא\u0004 \u0005[ש\u0006נבילה \u0005מטמאת],\u0006 \u0003אבל טריפה\u0004 שאינה מטמאה אין איסורה חמור כמותה, ולכן \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יחול על איסור חלב. \u0003ואי אשמעינן\u0004 \u0005[ואם היה משמיע לנו]\u0006 כן רק באיסור \u0003טריפה,\u0004 שהוא חל על איסור חלב, היה מקום לומר בטעם הדבר — \u0003משום\u0004 ש\u0003איסורה מחיים, אבל נבילה\u0004 שאינה נאסרת אלא לאחר מיתה \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יחול על איסור חלב. ולכן \u0003צריכא\u0004 \u0005[נצרכו]\u0006 שני המקראות.","עד כאן דנה הגמרא בשיטת ר' יהודה, הלמד מן המלה \"טריפה\" האמורה בטומאת נבלת העוף (ויקרא יז, טו), כי טריפת העוף, למרות שנשחטה — מטמאת בבית הבליעה, כנבילה. ושואלים: \u0003ור' מאיר,\u0004 הסבור ששחיטת עוף טריפה מוציאתו מכלל טומאת בית הבליעה, \u0003האי\u0004 \u0005[אותה]\u0006 \u0003\"טרפה\" מאי עביד ליה\u0004 \u0005[מה עושה לו,\u0006 כיצד הוא דורשו\u0005]?\u0006 ומשיבים: \u0003מיבעי ליה למעוטי\u0004 \u0005[נצרך לו למעט]\u0006 \u0003שחיטה\u0004 של עוף חולין \u0003שהיא\u0004 נעשית \u0003לפנים\u0004 (במקדש) שאינה מטמאת, למרות שהעוף נאסר באכילה.","ושואלים: \u0003ור' יהודה,\u0004 מנין הוא למד הלכה זו? ומשיבים: לשון \u0003\"טרפה\" אחרינא כתיב\u0004 \u0005[אחרת נאמרה]\u0006 בעניינה של טומאת בית הבליעה בנבלת עוף (\"נבלה וטרפה לא יאכל לטמאה בה\", ויקרא כב, ח) וממנה למדים הלכה זו.","ושואלים: \u0003ור' מאיר,\u0004 לשם מה נצרך לו גם כתוב זה? ומשיבים: \u0003חד\u0004 \u0005[אחד]\u0006 \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003שחיטה שהיא לפנים, וחד\u0004 \u0005[ואחד]\u0006 \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003עוף טמא\u0004 ללמד שנבלתו אינה מטמאת.","ושואלים: \u0003ור' יהודה,\u0004 מנין הוא למד שאינה מטמאת? ומשיבים: \u0003מ\u0004הכתוב \u0003\"נבלה...\u0004 לא יאכל לטמאה בה\" (ויקרא כב, ח) \u0003נפקא ליה\u0004 \u0005[יוצא,\u0006 נלמד \u0005לו],\u0006 משם הוא למד שרק מה שנאסר באכילה משום נבילה מטמא, ולא מה שאסור משום שהוא עוף טמא.","ושואלים: \u0003ור' מאיר האי\u0004 \u0005[\u0006מקרא \u0005זה]\u0006 \u0003\"נבלה...\u0004 לא יאכל\" \u0003מאי עביד לה\u0004 \u0005[מה עושה לו,\u0006 כיצד הוא דורשו\u0005]?\u0006 ומשיבים: מקרא זה בא \u0003ל\u0004השמיענו כי נבלת העוף מטמאת בבית הבליעה כשיש בה \u0003שיעור אכילה,\u0004 שהוא \u0003בכזית.\u0004","ושואלים על כך: \u0003ותיפוק\u0004 \u0005[ותצא,\u0006 ותילמד\u0005]\u0006 \u0003לי\u0004 הלכה זו \u0003מקרא קמא\u0004 \u0005[מהמקרא הראשון,\u0006 הקודם\u0005]:\u0006 \"וכל נפש אשר תאכל נבלה\" (ויקרא יז, טו), \u0003מדאפקיה רחמנא\u0004 \u0005[ממה שהוציאתו התורה]\u0006 \u0003בלשון אכילה!\u0004","ומשיבים: שני המקראות הללו נצרכו לענין שיעור אכילה המטמא, \u0003חד\u0004 \u0005[אחד]\u0006 \u0003לשיעור אכילה\u0004 שהוא \u0003בכזית, וחד\u0004 \u0005[ואחד]\u0006 \u0003לשיעור אכילה\u0004 שאינו נטמא אלא אם אוכל שיעור כזית \u0003בכדי\u0004 משך זמן של \u0003אכילת פרס\u0004 (חצי ככר לחם) ולא במשך זמן ארוך יותר.","ונצרך אף לימוד זה של כדי אכילת פרס, משום ש\u0003סלקא דעתך אמינא\u0004 \u0005[היה עולה על דעתך לומר]:\u0006 \u0003הואיל וחידוש הוא\u0004 שנבלת עוף טהור אינה מטמאת במגעה ובמשאה כשאר נבילה, אלא דווקא בעת היותה בבית הבליעה, אם אכל כזית מנבלת עוף גם ב\u0003יותר מכדי אכילת פרס נמי ליטמא\u0004 \u0005[גם כן שיטמא],\u0006 לכן \u0003קא משמע לן\u0004 \u0005[משמיע לנו\u0006 הכתוב\u0005]\u0006 שדווקא בכדי אכילת פרס הריהי מטמאה.","ושבים לדון בענין טומאת חלב נבילה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 מה שנאמר \u0003\"וחלב נבלה וחלב טרפה\u0004 יעשה לכל מלאכה\" (ויקרא ז, כד), ולמדים ממנו שאין החלב מטמא טומאת נבילה — \u0003בחלב בהמה טהורה הכתוב מדבר.\u0004","ודנים בדבר, \u0003אתה אומר: בחלב בהמה טהורה הכתוב מדבר, או אינו אלא בחלב בהמה טמאה?\u0004","\u0003אמרת\u0004 (אומר אתה) בתשובה לכך: הכתוב \u0003טיהר\u0004 את הבהמה מלטמא בטומאת נבילות \u0003מכלל\u0004 (מטעם) היותה \u0003שחוטה\u0004 כלומר, כאשר שוחטים אותה, \u0003ו\u0004כן \u0003טיהר\u0004 הכתוב מלטמא בטומאת נבילות \u0003מכלל\u0004 (מטעם) \u0003חלב,\u0004 שחלב נבילה אינו מטמא. ויש איפוא להשוותם: \u0003מה כשטיהר מכלל שחוטה\u0004 — \u0003בטהורה\u0004 טיהר \u0003ולא בטמאה,\u0004 שגם אם נשחטה הריהי מטמאת כנבילה, \u0003אף כשטיהר מכלל חלב\u0004 — \u0003בטהורה ולא בטמאה.\u0004","ויש לדון: \u0003או\u0004 שמא \u0003כלך\u0004 (לך) \u0003לדרך זו: טיהר\u0004 הכתוב \u0003מכלל\u0004 (מטעם) \u0003נבילה,\u0004 שנבלת בעל חיים טמא אינה מטמאת, \u0003ו\u0004כן \u0003טיהר\u0004 הכתוב נבילה מלטמא \u0003מכלל\u0004 (מטעם) \u0003חלב,\u0004 שחלב נבילה אינו מטמא, ויש איפוא להשוותם: \u0003מה כשטיהר מכלל נבילה\u0004 — \u0003בטמאה ולא בטהורה, אף כשטיהר מכלל חלב\u0004 — \u0003בטמאה ולא בטהורה!\u0004","\u0003אמרת\u0004 (אומר אתה) בתשובה לכך:"],["הואיל ו\u0003כש\u0004אתה \u0003בא בדרך זו\u0004 ולמד מדין שחיטה הלכה זו \u0003היא\u0004 דווקא \u0003בטהורה,\u0004 ו\u0003כש\u0004אתה \u0003בא בדרך זו\u0004 ולמד מדין נבילה \u0003היא\u0004 דווקא \u0003בטמאה,\u0004 אין אתה יכול ללמוד, איפוא, בדרך זו, וזקוק אתה להכרעת הכתוב — \u0003תלמוד לומר\u0004 בענין זה: \"וחלב נבלה וחלב \u0003טריפה\u0004 יעשה לכל מלאכה\" (ויקרא ז, כד), ומכאן למדנו שאין חלב נבילה טהור אלא חלבה של \u0003מי שיש במינה\u0004 איסור \u0003טריפה,\u0004 שהיא דווקא בהמה טהורה. אבל בהמה טמאה אסורה ממילא, ואין איסור טריפה חל עליה.","ויש לשאול: אם כך, \u0003אוציא את\u0004 חלבה של נבלת הבהמה \u0003הטמאה, ש\u0004כן \u0003אין במינה טריפה, ו\u0004אולם \u0003לא אוציא את\u0004 חלב נבלת \u0003החיה\u0004 הטהורה, \u0003ש\u0004כן \u0003יש במינה\u0004 איסור \u0003טריפה\u0004, ואף הוא לא יטמא! \u0003תלמוד לומר\u0004 באותו כתוב: \u0003\"ואכל לא תאכלוהו\",\u0004 ללמד: אין הדברים אמורים אלא בחלבו של \u0003מי ש\u0004רק \u0003חלבה אסור\u0004 באכילה \u0003ובשרה מותר\u0004 באכילה, שהיא הבהמה הטהורה. \u0003יצא\u0004 מכלל זה ה\u0003חיה, ש\u0004כן הן \u0003חלבה ו\u0004הן \u0003בשרה מותר\u0004 באכילה.","ועל מה ששנינו בסוף ברייתא זו: כשטיהר מכלל נבילה — בטמאה ולא בטהורה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יעקב בר אבא לרבא: אלא מעתה\u0004 משמע מנוסח דברים זה ש\u0003נבלת בהמה טהורה הוא\u0004 ש\u0003מטמאה,\u0004 ואילו \u0003נבלת בהמה טמאה לא מטמאה? אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003כמה סבי שבישתו\u0004 \u0005[זקנים\u0006 שכמותכם \u0005הטעיתם]\u0006 \u0003בה\u0004 בהבנת ברייתא זו, שכן \u0003סיפא אתאן\u0004 \u0005[בסוף\u0006 הברייתא \u0005באנו]\u0006 \u0003ל\u0004עניינה של \u0003נבלת עוף טמא,\u0004 והיא אכן אינה מטמאה. שנינו במשנתנו כי לדעת ר' מאיר, עוף שנמלק ונמצא שהוא טריפה — טיהרה אותו מליקתו מטומאת נבילה. \u0003אמר ר' יוחנן: לא טיהר ר' מאיר\u0004 את העוף אם נמלק, \u0003אלא ב\u0004עופות \u0003תמימין,\u0004 הראויים מעיקרם לקרבן, אלא שנמצא שהיו טריפה. \u0003אבל בבעלי מומין,\u0004 שאינם ראויים מתחילתם להקרבה \u0003—\u0004 \u0003לא. ור' אלעזר אמר: אפילו בבעלי מומין\u0004 מטהר ר' מאיר, הואיל ומליקה מטהרת בתמימים. ומעירים: \u0003איתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 באותו ענין, \u0003אמר רב ביבי\u0004 שכך \u0003אמר ר' אלעזר: מטהר היה ר' מאיר\u0004 אף \u0003בבעלי מומין, ואפילו באווזין ותרנגולין\u0004 שאין במינם דבר הקרב על המזבח, ואין במינם מליקה כלל.","","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' ירמיה:\u0004 לפי הסברו של ר' אלעזר בשיטת ר' מאיר, אם \u0003ערף עז\u0004 כדרך שעורפים עגלה על חלל שנמצא בסמוך לעיר ואין ידוע מי הרגו (ראה דברים כא, ד), \u0003מהו\u0004 דינה לענין טומאת נבילות הנוהגת בבהמות?","וצדדי השאלה: \u0003אווזין ותרנגולין\u0004 \u0003טעמא מאי\u0004 \u0005[הטעם\u0006 לטהרם במליקה \u0005מהו]?\u0006 משום \u0003דמינא דעופות נינהו\u0004 \u0005[שמין של עופות הם]\u0006 שיש בהם מליקה. \u0003אבל עז לאו מינא דעגלה נינהו\u0004 \u0005[לא בני מינה של עגלה הם],\u0006 שכן עז הריהי בהמה דקה ואילו עגלה הריהי בהמה גסה. \u0003או דילמא\u0004 \u0005[שמא]\u0006 מן הצד האחר, כיון שאף עז \u0003מינא\u0004 \u0005[מין]\u0006 של \u0003בהמה הוא,\u0004 הריהי כעגלה שנערפה, ולא תטמא?","\u0003יתיב\u0004 \u0005[יושב היה]\u0006 \u0003רב דימי וקאמר לה להא שמעתא\u0004 \u0005[ואומר את השמועה,\u0006 הבעיה \u0005הזו],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: מכלל\u0004 הדיון בעז ערופה אתה מניח ש\u0003עגלה ערופה\u0004 עצמה \u0003טהורה היא\u0004 מלטמא כנבילה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן],\u0006 שכך \u0003אמרי דבי\u0004 \u0005[אמרו\u0006 החכמים \u0005של בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ינאי: כפרה כתיב\u0004 \u0005[נאמר]\u0006 \u0003בה\u0004 בעגלה ערופה \u0003כקדשים\u0004 (\"כפר לעמך ישראל אשר פדית ה' ואל תתן דם נקי בקרב עמך ישראל ונכפר להם הדם\". דברים כא, ח), ועריפתה הריהי איפוא כמליקת עופות קדשים, שמטהרתם מטומאת נבילה.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב נתן אבוה\u0004 \u0005[אביו]\u0006 של \u0003רב הונא (בר נתן),\u0004 ממה ששנינו בברייתא בענין חלב בהמה טהורה, שאינו מטמא טומאת נבילה: \"וחלב נבלה וחלב טרפה יעשה לכל מלאכה \u0003ואכל לא תאכלוהו\"\u0004 (ויקרא ז, כד) — \u0003אין לי אלא חלב שאסור באכילה ומותר בהנאה,\u0004 ואולם \u0003חלב של שור הנסקל\u0004 שנדון למיתה \u0003ו\u0004של \u0003עגלה ערופה,\u0004 שאסורים באכילה ובהנאה, \u0003מנין\u0004 שאף הם אינם מטמאים? \u0003תלמוד לומר: \"כל חלב...\u0004 לא תאכלו\" (ויקרא ג, יז), להשוות דינם. \u0003ו\u0004מעתה, \u0003אי סלקא דעתך\u0004 \u0005[אם עולה על דעתך]\u0006 לומר ש\u0003עגלה ערופה\u0004 שנערפה \u0003טהורה היא,\u0004 מה מקום יש להצריך כתוב שילמדנו שאין חלבה מטמא? וכי יתכן ש\u0003היא טהורה וחלבה\u0004 יהא \u0003טמא?!\u0004","","","ומשיבים: \u0003היכא דערף מיערף\u0004 \u0005[במקום שערף]\u0006 את העגלה כדין \u0003לא איצטריכא ליה\u0004 \u0005[הוצרכה לו]\u0006 דרשה זו. \u0003כי איצטריכא\u0004 \u0005[כאשר הוצרכה]\u0006 דרשה זו לטהר את חלבה, הריהו \u0003היכא דשחטה מישחט\u0004 \u0005[במקום ששחט אותה].\u0006","ומקשים: \u0003ותיהני ליה\u0004 \u0005[ותועיל לו]\u0006 \u0003שחיטה לטהרה מידי\u0004 טומאת \u0003נבלה!\u0004 ומשיבים: אלא \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 דרשה זו אלא לחלב עגלה ערופה \u0003שמתה\u0004 לפני שנערפה, שאף שבשרה מעתה מטמא בטומאת נבילה, חלבה אינו מטמא.","ושואלים: אם במקרה זה מדובר בברייתא, האם \u0003מכלל\u0004 זה ניתן ללמוד שהעגלה המיועדת לעריפה, כבר \u0003מחיים\u0004 הריהי \u0003אסורה\u0004 בהנאה? שהרי משום כך הוצרכנו לדרשה זו. ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 שכך \u0003אמר ר' ינאי: גבול שמעתי\u0004 בדין עגלה ערופה, שממנו והלאה הריהי אסורה, \u0003ו\u0004אולם \u0003שכחתי\u0004 מהו, \u0003ונסבין חברייא למימר\u0004 \u0005[ונושאים החברים,\u0006 החכמים, דעתם \u0005לומר]:\u0006 \u0003ירידתה\u0004 של העגלה \u0003לנחל איתן\u0004 כדי להיערף שם \u0003היא אוסרתה.\u0004","","\u0003כל הזבחים\u0004 (בהמות העומדות להקרבה) \u0003שנתערבו ב\u0004בהמה שאסורה בהנאה, כגון באחת מה\u0003חטאות המתות\u0004 (שנפסלו ודינן למיתה) \u0003או\u0004 שנתערבו \u0003בשור הנסקל\u0004 (שנידון לסקילה על שהרג אדם), \u0003אפילו\u0004 בהמה \u0003אחת\u0004 האסורה בהנאה שנתערבה \u0003בריבוא\u0004 בהמות העומדות להקרבה — הרי אלו אסורים בהנאה, ו\u0003ימותו כולן.\u0004 ואולם אם \u0003נתערבו\u0004 זבחים \u0003ב\u0004בהמות האסורות בהקרבה אבל אינן אסורות בהנאה, כגון שור עולה שנתערב ב\u0003שור שנעבדה\u0004 (שנעשתה) \u0003בו עבירה\u0004 שהוא נפסל על ידה להקרבה, \u0003או\u0004"],["בשור \u0003שהמית את האדם\u0004, ואין הדבר ידוע לבית הדין על פי שני עדים המעידים על כך (שאז היה דינו לסקילה, והריהו אסור בהנאה), אלא \u0003על פי עד אחד\u0004 בלבד, \u0003או\u0004 \u0003על פי\u0004 הודאת \u0003הבעלים\u0004 עצמם. וכן אם התערב זבח \u0003ברובע\u0004 (בעל חיים שרבע אשה), \u0003ו\u0004ב\u0003נרבע\u0004 (על ידי איש), או שנתערבו \u0003במוקצה\u0004 (בעל חיים שיוחד לעבודה זרה), \u0003ו\u0004ב\u0003נעבד\u0004 כעבודה זרה, או שנתערבו \u0003ב\u0004בעל חיים שניתן כ\u0003אתנן\u0004 זונה, \u0003ומחיר\u0004 כלב, כאמור: \"לא תביא אתנן זונה ומחיר כלב בית ה' אלקיך\" (דברים כג, יט)."],["וכן אם נתערב זבח \u0003ב\u0004בהמה של \u0003כלאים\u0004 (כגון הנולד מאיל ועז), \u0003וב\u0004בהמה שהיא \u0003טריפה,\u0004 ו\u0003ביוצא דופן\u0004 (שיצא מבטן אמו לא בהמלטה רגילה אלא בחיתוך דופן הרחם), שכל אלה אמנם פסולים להקרבה, אך אין הם אסורים להדיוט לכשייפדו. ולכן הבהמות שבתערובת \u0003ירעו עד שיסתאבו\u0004 (שיפול בהן מום, וייפסלו להקרבה) \u0003ו\u0004לאחר מכן \u0003ימכרו, ו\u0004מן הכסף המתקבל \u0003יביא\u0004 הבעלים קרבן אחר, \u0003ב\u0004שווי \u0003דמי\u0004 הבהמה \u0003ה\u0004יותר \u0003יפה\u0004 (משובחת) \u0003שבהן\u0004 שהיתה בתערובת, \u0003מאותו המין\u0004 של הקרבן אותו הוא צריך להקריב.","\u0003נתערבו\u0004 זבחים \u0003ב\u0004בהמות \u0003חולין תמימים\u0004 (שאין בהם מום, וראויים להקרבה) — \u0003ימכרו החולין לצורכי\u0004 קרבנות מ\u0003אותו המין\u0004 של הקרבן שנתערב בהם.","נתערבו בהמות \u0003קדשים\u0004 של אדם זה \u0003בקדשים\u0004 של אדם אחר, והיתה זו תערובת של \u0003מין במינו\u0004 (אותו סוג קרבן), ואין הבעלים יודעים עתה מהם קרבנותיהם, מה יעשו? \u0003[זה יקרב לשם מי שהוא\u0004 בעליו, \u0003וזה] יקרב לשם מי שהוא\u0004 בעליו, ויצאו שניהם ידי חובתם.","ואולם אם היו אלה \u0003קדשים בקדשים מין בשאינו מינו\u0004 כגון אדם שהביא שני אילים, אחד לעולה ואחד לשלמים, ונתערבו שניהם, שאין מעשה הקרבתם שווה — \u0003ירעו עד שיסתאבו וימכרו, ו\u0004מן הכסף המתקבל \u0003יביא\u0004 הבעלים, \u0003ב\u0004שווי \u0003דמי\u0004 האיל היותר \u0003יפה שבהן,\u0004 קרבן \u0003ממין זה\u0004 (עולה), \u0003ו\u0004כן יביא \u0003בדמי היפה שבהן\u0004 קרבן \u0003ממין זה\u0004 (שלמים), \u0003ויפסיד\u0004 בכך את \u0003המותר,\u0004 ההפרש שבין מחירם של שני הקרבנות, \u0003מביתו\u0004 (משלו).","\u0003נתערבו\u0004 קרבנות \u0003בבכור\u0004 בהמה \u0003ו\u0004כן \u0003במעשר\u0004 בהמה, ששני אלה אינם נמכרים גם כשנופל בהם מום, מה יעשו? \u0003ירעו\u0004 אלו ואלו \u0003עד שיסתאבו,\u0004 ויפדה את הקדשים האחרים, כך שיהו מותרים. \u0003ו\u0004מאחר שאינו יודע איזו מן הבהמות בכור או מעשר \u0003יאכלו\u0004 כולם \u0003כ\u0004כל דיני אכילת \u0003בכור וכמעשר\u0004 שנפל בהם מום, שאין נוהגים בהם מנהג חולין.","ובענין ששנינו על קדשים שנתערבו זה בזה, מעירים: \u0003הכל\u0004 כל מיני הקרבנות כולם \u0003יכולין\u0004 (אפשר להם) \u0003להתערב\u0004 בלא שנדע מהו כל קרבן, \u0003חוץ מן החטאת והאשם\u0004 שאינם באים לעולם מאותה בהמה, שהאשם אינו אלא איל או כבש, והחטאת לעולם אינה באה מאחד מהם.","שנינו במשנה: \"כל הזבחים שנתערבו בחטאות המתות או בשור הנסקל\" וכו', ומלשון זו משמע שבהמה אחת מן הזבחים הכשרים התערבה ברוב של בהמות אסורות. ושואלים על כך: אם כן הוא, \u0003מאי\u0004 \u0005[מהו]\u0006 הלשון \u0003\"אפילו\u0004 אחת בריבוא ימותו כולן\", שמשמעה שבאה לחדש שאף במקרה זה ימותו כולם? והרי כל שכן שבמקרה כזה, שהקרבן הכשר התערב בעשרת אלפים קרבנות פסולים, שימותו כולם!","ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך הוא אומר,\u0006 זו כוונת דברי התנא שבמשנה\u0005]\u0006 \u0003: כל הזבחים\u0004 הכשרים \u0003שנתערבו בהן חטאות המתות או שור הנסקל, אפילו\u0004 היה הפסול \u0003אחד\u0004 שהתערב \u0003בריבוא\u0004 קרבנות כשרים — \u0003ימותו כולן.\u0004 ומבררים עוד: למה לנו לשנות הלכה זו שבמשנתנו?","והלוא \u0003תנינא חדא זימנא\u0004 \u0005[שנינו\u0006 כבר אותה \u0005פעם אחת]\u0006 במסכת תמורה: \u0003כל\u0004 בעלי החיים \u0003האסורין ל\u0004הקרבה על \u0003גבי\u0004 ה\u0003מזבח\u0004 שהתערבו בקרבנות כשרים — \u0003אוסרין\u0004 אותם להקרבה אפילו \u0003בכל שהן,\u0004 והמשנה מפרטת את הפסולים להקרבה: שור \u0003הרובע ו\u0004שור \u0003הנרבע!\u0004","\u0003אמר רב אשי: אמריתה לשמעתיה קמיה\u0004 \u0005[אמרתי את השמועה,\u0006 הדיון הזה \u0005לפני]\u0006 \u0003רב שימי, ואצריכן\u0004 \u0005[והצריך לנו]\u0006 את שני המשניות הללו, שבכל אחת יש חידוש דין שאין באחרת: \u0003דאי מהתם\u0004 \u0005[שאם משם,\u0006 מהמשנה האחרת\u0005]\u0006 בלבד, \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה,\u0006 שהבהמות האסורות אוסרות את תערובתן בכל שהוא\u0005]\u0006 אמורים דווקא לאוסרן \u0003לגבוה\u0004 (להקרבה על המזבח), \u0003אבל ל\u0004אוסרן אף לשימושו של ה\u0003הדיוט,\u0004 וכגון שנתערב בהן שור הנסקל, ולומר שימותו כולן, בלא אפשרות לפדותן — \u0003אימא\u0004 \u0005[אומר]\u0006 ש\u0003לא\u0004 כך ההלכה, אלא ייבטלו ברוב, כדין כל איסורים שבתורה.","\u0003ואי מהכא\u0004 \u0005[ואם מכאן,\u0006 ממשנתנו\u0005]\u0006 \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 דווקא \u0003הני\u0004 \u0005[אלה]\u0006 הנזכרים במשנתנו, חטאות המתות ושור הנסקל, \u0003הוא\u0004 שאוסרים את התערובת בכלשהו, משום שחמור דינם, שהרי \u0003איסורי הנאה נינהו\u0004 \u0005[הם],\u0006 \u0003אבל הני\u0004 \u0005[אלה]\u0006 הנזכרים במשנה האחרת, רובע ונרבע ושאר פסולי הקרבה, שאינם איסורי הנאה, ומותרים לשימוש ההדיוט (לכשייפדו), \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 שאין הם אוסרים את כל התערובת להקרבה, ובטלים ברוב. לכן \u0003צריכי\u0004 \u0005[נצרכות]\u0006 שתי המשניות.","ושואלים: ואת דינם של אלו \u0003דלאו\u0004 \u0005[שאינם]\u0006 \u0003איסורי הנאה נינהו\u0004 \u0005[הם],\u0006 כגון הרובע והנרבע, מדוע הוצרך לשנותו במסכת תמורה? \u0003הא תנא ליה\u0004 \u0005[הרי\u0006 כבר \u0005שנה אותו\u0006 במשנתנו\u0005]\u0006 שלא ניתן להקריב את תערובתם! ומשיבים: אמנם כן, ואולם \u0003מי קתני\u0004 \u0005[האם\u0006 גם \u0005שנה]\u0006 במשנתנו \u0003בכמה\u0004 באיזה יחס מספרי הם אוסרים את תערובתם? והרי השיעור \u0003\"כל שהן\" התם קתני\u0004 \u0005[שם שנה\u0006 אותו\u0005],\u0006 ולא במשנתנו, ולכך הוצרכה אותה משנה.","ושואלים: \u0003וניתני הא\u0004 \u0005[ושישנה\u0006 את \u0005זו]\u0006 שבמסכת תמורה, \u0003ולא בעי הא\u0004 \u0005[יצטרך\u0006 את \u0005זו,\u0006 משנתנו\u0005]\u0006 כלומר, את דינם של אלו שאינם אסורים בהנאה! ומשיבים: \u0003תקנתא איצטריכא ליה\u0004 \u0005[התקנה,\u0006 דרך התיקון, של תערובת כזו, \u0005נצרכה לו,\u0006 לתנא\u0005]\u0006 להשמיעה במשנתנו, שירעו עד שיסתאבו, וימכרו, ויביא בדמי היפה שבהן מאותו המין.","וחוזרים ושואלים: דין משנתנו, שאיסורי הנאה אוסרים את תערובתם בכל שהוא אף על ה\u0003הדיוט,\u0004 וכפי ששנינו בחטאות המתות ושור הנסקל, הרי \u0003נמי תנא ליה\u0004 \u0005[גם כן\u0006 כבר \u0005שנה אותו]\u0006 במשנה במסכת עבודה זרה: \u0003ואלו אסורין\u0004 בהנאה \u0003ואוסרין\u0004 את תערובתם \u0003בכל שהן: יין נסך\u0004 כשנתערב ביין כשר, \u0003ועבודה זרה\u0004 שנתערבה בדברי היתר, ושור הנסקל שנתערב בשוורים מותרים!"],["ומשיבים: \u0003צריכי\u0004 \u0005[צריכות]\u0006 שתי המשניות הללו להישנות, \u0003דאי מהתם\u0004 \u0005[שאם משם]\u0006 מהמשנה שבמסכת עבודה זרה, \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 דין זה הוא דווקא כשנתערבה הבהמה האסורה בבהמות חולין, והכל נאסר \u0003להדיוט, אבל\u0004 כשנתערבה בבהמות קדשים, שמיועדות \u0003לגבוה\u0004 (להקדש) ויש בכך הפסד קדשים — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא נפסדינהו לכולהו\u0004 \u0005[נפסיד את כולם\u0006 כל הקרבנות הכשרים\u0005],\u0006 ודי ברוב רגיל כדי לבטל בהם את האיסור, לכך נצרכה להישנות אף משנתנו.","\u0003ו\u0004מן הצד האחר, \u0003אי מהכא\u0004 \u0005[אם מכאן,\u0006 ממשנתנו\u0005]\u0006 בלבד, \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שכל התערובת נאסרת, אמורים דווקא ב\u0003קדשים\u0004 — משום \u0003דמאיס\u0004 \u0005[שמאוס,\u0006 מגונה\u0005]\u0006 הדבר להקריב לפני המקום מתערובת שכזו, שיש בה בהמה אסורה, \u0003אבל\u0004 לענין שימוש של \u0003חולין\u0004 מתערובת שכזו, \u0003דלא מאיס\u0004 \u0005[שאין\u0006 הדבר \u0005מאוס]\u0006 — \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003איסורי הנאה ליבטלי ברובא\u0004 \u0005[שייבטלו ברוב],\u0006 על כן \u0003צריכא\u0004 \u0005[נצרכה]\u0006 אף המשנה שבמסכת עבודה זרה.","ושואלים: \u0003ו\u0004באמת, מדוע לא נאמר כי \u0003ניבטלו\u0004 \u0005[ייבטלו]\u0006 הבהמות האסורות בהנאה \u0003ברובא\u0004 \u0005[ברוב],\u0006 כמו שאר דברים שבתורה! \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 בתשובה: \u0003חשיבי\u0004 \u0005[חשובים]\u0006 הם לעצמם, שכל בהמה נמנית לעצמה, \u0003ו\u0004לכן הם \u0003לא בטלי\u0004 \u0005[בטלים]\u0006 ברוב, ואולם \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006דעת \u0005מי שאומר]\u0006 בענין זה: \u0003כל\u0004 דבר \u0003שדרכו לימנות\u0004 (להיספר) כשמוכרים אותו, \u0003שנינו\u0004 שאיננו בטל ברוב מחמת חשיבותו, גם אם לעתים הוא נמכר כחלק מחבילה. כגון בהמה, שיש שהיא נמכרת כחלק מעדר ולא לפי מנין מדוייק.","\u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]:\u0006 דווקא \u0003את\u0004 \u0003שדרכו לימנות\u0004 תמיד \u0003שנינו\u0004 שאיננו בטל ברוב, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 מדוע בהמה אינה בטלה ברוב? והרי יש והיא נמכרת כחלק מעדר! ומה היא אותה מחלוקת? \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003מי שהיו לו חבילי תילתן,\u0004 שהוא תבלין חשוב, \u0003של כלאי הכרם,\u0004 כלומר, שנזרע בתוך כרם,"],["\u0003ידלקו\u0004 (יישרפו באש) שכן כלאי הכרם אסורים בהנאה. \u0003נתערבו\u0004 חבילות תלתן אלה \u0003באחרים (ואחרים באחרים)\u0004 — אין חבילות התלתן האסורות בטלות ברוב, והרי הן אוסרות את שאר החבילות שבתערובת, ולכן \u0003כולן ידלקו, דברי ר' מאיר. וחכמים אומרים: יעלו\u0004 (יתבטלו) החבילות האסורות \u0003ב\u0004שיעור של \u0003אחד ומאתים.\u0004 שאם היו מאתיים או יותר כנגד האיסור, הרי הוא בטל.","ומסבירים את שיטותיהם, \u0003ש\u0004כך \u0003היה ר' מאיר אומר: כל\u0004 דבר \u0003שדרכו למנות\u0004 (להימנות, להיספר) אחד אחד — הרי הוא חשוב ואינו בטל, ולפיכך \u0003מקדש\u0004 (אוסר) את כל התערובת בה הוא התערב. ואף חבילות אלה דרכן להימנות. \u0003וחכמים אומרים: אינו מקדש\u0004 את תערובתו \u0003אלא ששה דברים בלבד,\u0004 שיש להם חשיבות יתירה. ואילו \u0003ר' עקיבא אומר שבעה. ואלו הן: אגוזי פרך\u0004 אגוזים מיוחדים, שקליפתם נפרכת (נשברת) בקלות, \u0003ורימוני\u0004 המקום \u0003באדן וחביות\u0004 יין \u0003סתומות, וחילפי תרדין, וקילחי\u0004 (גבעולי) \u0003כרוב, ודלעת יונית.\u0004 ו\u0003ר' עקיבא מוסיף\u0004 עליהם \u0003אף ככרות\u0004 לחם \u0003של בעל הבית.\u0004","ומן הדברים הללו, זה \u0003הראוי ל\u0004איסור \u0003ערלה\u0004 כגון אגוזים ורימונים וחביות יין, שהם מפרי העץ ויש בהם איסור ערלה — מקדש תערובתו לענין \u0003ערלה,\u0004 וזה \u0003הראוי ל\u0004איסור \u0003כלאי הכרם\u0004 תרדים, כרוב ודלעת \u0003—\u0004 מקדש את תערובתו באיסור \u0003כלאי הכרם.\u0004","\u0003ואיתמר עלה\u0004 \u0005[ונאמר עליה\u0006 על משנה זו\u0005]\u0006 שנחלקו אמוראים ביחס לנוסח המדוייק של שיטת ר' מאיר שבמשנה, \u0003ר' יוחנן אמר: \"את שדרכו למנות\u0004 מקדש\" \u0003שנינו\u0004 כלומר, מה שנמכר אך ורק במנין, \u0003ר' שמעון בן לקיש אומר: \"כל שדרכו למנות\u0004 מקדש\" \u0003שנינו,\u0004 וגם מה שלעתים נמכר בלא מנין.","ואם כן, מה ששנינו במשנתנו, שבעלי חיים אינם בטלים ברוב — \u0003הניחא\u0004 \u0005[זה נוח]\u0006 \u0003לריש לקיש, אלא לר' יוחנן מאי איכא למימר\u0004 \u0005[מה יש לומר]\u0006? והרי פעמים מוכרים בעלי חיים כעדר! \u0003אמר רב פפא: האי תנא\u0004 \u0005[תנא זה\u0006 של המשנה שבדין כלאי הכרם\u0005]\u0006 ה\u0003תנא\u0004 ששנה בענין \u0003ליטרא קציעות הוא, דאמר\u0004 \u0005[ש\u0006הוא \u0005אומר,\u0006 שסובר\u0005]:\u0006"],["\u0003כל דבר שיש בו מנין\u0004 שלפעמים מונים אותו, \u0003אפילו ב\u0004דבר שאיסורו \u0003דרבנן\u0004 \u0005[מדברי סופרים]\u0006 — \u0003לא בטיל\u0004 \u0005[בטל]\u0006 כמו תרומת פירות, \u0003וכל שכן\u0004 \u0003ב\u0004איסור שהוא \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 כמו בהמות פסולות להקרבה \u0005שבמשנתנו.\u0006","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ליטרא\u0004 (מידת משקל) של \u0003קציעות\u0004 (תאנים מיובשות) של תרומה \u0003שדרסה על פי עיגול\u0004 (כלי המיועד לעשיית עיגולי דבילה) שיש בו קציעות רבות של חולין, וליטרא שבפיו ניכרת לעצמה. והיו לפניו עיגולים רבים, ובפיהם ליטרות של קציעות חולין, \u0003ואינו יודע ב\u0004פיו של \u0003איזו עיגול דרסה.\u0004 או שדרס ליטרא קציעות של תרומה \u0003על פי חבית\u0004 שיש בה קציעות חולין \u0003ואינו יודע ב\u0004פיה של \u0003איזו חבית\u0004 מן החביות שלפניו \u0003דרסה.\u0004 או שדרסה \u0003על פי כוורת\u0004 שמאחסנים בה קציעות \u0003ואינו יודע ב\u0004פיה של \u0003איזו כוורת\u0004 מן הכוורות שלפניו \u0003דרסה.\u0004","\u0003ר' מאיר אומר: ר' אליעזר\u0004 היה \u0003אומר: רואין את העליונות\u0004 את הקציעות המדובקות יחד שבפי הכלי \u0003כאילו הן פרודות\u0004 זו מזו, ומעורבות יחד עם הקציעות האחרות שבתוך הכלי, \u0003והתחתונות מעלות\u0004 (מבטלות) \u0003את העליונות,\u0004 אם יש בהן כשיעור מאה ליטרות, שתרומה בטלה במאה.","ואילו \u0003ר' יהושע אומר: אם יש מאה פומין\u0004 (פיות), כלומר, אם היו באותו מקום מאה כלים ובפיו של כל אחד מהם דחס ליטרא קציעות (של חולין) — \u0003יעלו\u0004 (יתבטלו) ליטרת קציעות התרומה במאה, \u0003ואם לאו\u0004 \u0005[לא]\u0006 — כל \u0003הפומין אסורין,\u0004 שמא קציעות תרומה הוא אוכל. \u0003וה\u0004קציעות הנמצאות ב\u0003שולים\u0004 (תחתית) של כל הכלים הללו הריהן \u0003מותרין,\u0004 שכיון שברור לו שהקציעות האסורות אינן שם, אין הן בכלל הספק.","ואילו \u0003ר' יהודה אומר\u0004 באופן שונה את מחלוקתם של ר' אליעזר ור' יהושע, שכך היה \u0003ר' אליעזר אומר: אם יש שם מאה פומין\u0004 ובפיהם קציעות — \u0003יעלו, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003ה\u0004קציעות שב\u0003פומין אסורין,\u0004 והקציעות שבשוליים מותרות.","ואילו \u0003ר' יהושע אומר: אפילו יש שם שלשה מאות פומין\u0004 ובפיהם ליטרות קציעות — \u0003לא יעלו\u0004 את ליטרת הקציעות של התרומה, משום שהיא דבר שיש בו מנין, שיש שאדם מוכר ליטרות קציעות במנין.","אבל \u0003דרסה\u0004 לאותה ליטרא של קציעות תרומה \u0003בעיגול, ואינו יודע באיזה מקום בעיגול דרסה, או לצפונה או לדרומה\u0004 — \u0003דברי הכל יעלו,\u0004 שהרי אינה ניכרת כלל לעצמה. ויש לומר, איפוא, שמשנתנו בענין בהמות פסולות להקרבה, שאינן בטלות, היא כשיטת ר' יהושע לפי דברי ר' יהודה, שכל שדרכו לימנות אינו בטל. ומה שאמר ר' יוחנן שרק מה שדרכו לימנות תמיד אינו בטל, הרי לשיטת ר' מאיר נאמר.","\u0003רב אשי אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 כי משנתנו \u0003רבנן\u0004 \u0005[\u0006שיטת \u0005חכמים\u0006 היא\u0005],\u0006 כלומר, ר' מאיר, הסבור שדבר שאינו נמנה תמיד בטל ברוב, יש להבין כי \u0003בעלי חיים חשיבי\u0004 \u0005[חשובים]\u0006 הם, \u0003ו\u0004לכן הם \u0003לא בטלי\u0004 \u0005[בטלים].\u0006","ושואלים: הרי יש דרך אחרת להתיר את כל תערובת הקרבנות, \u0003ו\u0004כך יעשו: \u0003נמשוך ונקרב חד מינייהו\u0004 \u0005[ונקריב אחד מהם],\u0006 \u0003ונימא\u0004 \u0005[ונאמר]:\u0006 \u0003כל דפריש מרובא פריש\u0004 \u0005[כל שפורש\u0006 מתערובת שיש בה רוב ומיעוט, \u0005מהרוב\u0006 הוא \u0005פורש],\u0006 ואם כן, זה שנלקח מן התערובת היה כשר. וכך נעשה עד שישארו שנים מן התערובת! על העצה הזו תוהים: \u0003נמשוך\u0004 מן התערובת? \u0003הוה לה\u0004 \u0005[הרי זה]\u0006 מתוך דבר שהוא \u0003קבוע,\u0004 כלומר, תערובת שהאיסור שבה קבוע במקומו,"],["\u0003וכל\u0004 תערובת שהאיסור שבה \u0003קבוע\u0004 במקומו, אין הוא בטל ברוב, אלא \u0003כמחצה על מחצה דמי\u0004 \u0005[\u0006הוא \u0005נחשב]!\u0006 ומשיבים: \u0003אלא\u0004 כך יש לשאול, \u0003ניכבשינהו דניידי\u0004 \u0005[נדחוק אותם\u0006 את כל הבהמות שבתערובת, כך \u0005שינודו]\u0006 כולן ממקומן, ובכך תתבטל הקביעות של האיסור, \u0003ו\u0004מעתה \u0003נימא\u0004 \u0005[נאמר]\u0006 על כל אחת ואחת מהן: \u0003כל דפריש\u0004 \u0005[שפורש]\u0006 \u0003מרובא פריש\u0004 \u0005[מהרוב\u0006 הוא \u0005פורש],\u0006 ויהיו מותרות!","\u0003אמר רבא: (השתא דאמור רבנן דלא ניקרב\u0004 \u0005[עכשיו שאמרו חכמים שלא נקריב\u0006 מהם\u0005]\u0006\u0003)\u0004 הרי זה משום \u0003גזירה, שמא\u0004 לאחר מכן \u0003יבאו עשרה כהנים בבת אחת ויקרבו\u0004 את כל הבהמות שבתערובת כאחת, ולא כל אחת לעצמה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ההוא מרבנן\u0004 \u0005[אחד מהחכמים]\u0006 \u0003לרבא: אלא מעתה,\u0004 לפי הסבר זה, אתה מניח כי \u0003מגיסא אסירא\u0004 \u0005[המגיס,\u0006 הכלי בו מניחים את אימורי הבהמה כדי להקטירם, יהיה \u0005אסור]?\u0006 כלומר, וכי הבהמות שהותרו מתחילה, כשפרשו ממקומן, חוזרות ונאסרות כשיחזרו ויתערבו?","השיב לו רבא: כוונתי לא היתה שמא לאחר מכן יקריבו עשרה כהנים כאחד, אלא גזירה \u0003משום שמא\u0004 כשינודו הבהמות ממקומן \u0003יבאו עשרה כהנים בבת אחת ויקחו,\u0004 ובמקרה זה, כיון שכל התערובת (או רובה) פורשת כאחת — יש להניח שהאיסור מצוי בין הפורשים, ואין מתירים אותם. ותמהים: מקרה כזה \u0003בעשרה כהנים\u0004 שיקחו \u0003בבת אחת מי\u0004 \u0005[האם]\u0006 \u0003אפשר\u0004 שיקרה? \u0003אלא אמר רבא\u0004 טעם אחר: אין מתירים את התערובת באופן של \u0003ניוד הבהמות\u0004 \u0003משום\u0004 גזירה, שמא יבואו להתיר אף בנוטל מן ה\u0003קבוע.\u0004","ועוד \u0003אמר רבא\u0004 בהלכה זו: \u0003השתא דאמרי רבנן\u0004 \u0005[עכשיו שאמרו חכמים]\u0006 במשנתנו ש\u0003לא נקריב\u0004 \u0005[יקריב]\u0006 מן הבהמות שבתערובת, \u0003אי נקריב לא מרצי\u0004 \u0005[אם יקריב אינו מרצה],\u0006 וצריך להביא קרבן אחר. \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב הונא בר יהודה לרבא\u0004 ממה ששנינו במשנה במסכת קינים: \u0003חטאת\u0004 העוף \u0003שנתערבה בעולה ועולה שנתערבה בחטאת, אפילו\u0004 נתערבו \u0003אחת בריבוא\u0004 — \u0003ימותו כולן,\u0004 שהרי אין להן תקנה.","\u0003במה דברים אמורים? בכהן נמלך\u0004 שבא לבית דין לשאול מה עליו לעשות. \u0003אבל בכהן שאין נמלך\u0004 והלך על דעת עצמו והקריבן, אם היה שם מנין שווה של עופות חטאת ושל עופות עולה, ו\u0003עשאן\u0004 את כולן \u0003למעלה\u0004 מחוט הסיקרא שבאמצע המזבח, כמעשה העולה — נמצא \u0003מחצה כשר\u0004 העולות שנעשו במקומן, \u0003ומחצה פסול\u0004 החטאות שנעשו שלא במקומן.","וכן אם עשאן את כולן \u0003למטה\u0004 מחוט הסיקרא — \u0003מחצה כשר ומחצה פסול.\u0004 ואם עשה \u0003אחת למטה ואחת למעלה\u0004 — \u0003שניהן פסולות, שאני\u0004 חושש ו\u0003אומר:\u0004 שמא ה\u0003חטאת\u0004 היא זו ש\u0003קריבה למעלה ו\u0004ה\u0003עולה\u0004 היא זו ש\u0003קריבה למטה.\u0004 ומכאן שקרבן שאסרו חכמים בהקרבה מחמת איסור שנתערב בו, הריהו מרצה בדיעבד, שלא כדברי רבא!","\u0003אלא\u0004 לשיטת רבא יש לומר שהדבר תלוי במחלוקת תנאים, \u0003הא כמאן דאמר\u0004 \u0005[זו\u0006 שאמר רבא, הרי זה \u0005כ\u0006שיטת \u0005מי שאומר]\u0006 \u0003בעלי חיים\u0004 שנפסלו פעם אחת להקרבה \u0003נדחין\u0004 לגמרי, והרי מתחילה נאסרה הבהמה מחמת התערובת. ואילו \u0003הא כמאן דאמר\u0004 \u0005[זו\u0006 המשנה בקינים היא \u0005כ\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003בעלי חיים\u0004 שנדחו מהקרבה מחמת התערובת \u0003אינן נידחין\u0004 לגמרי, ולכן, אם הקריבם כראוי הרי אלו כשרים.","ומקשים: \u0003הרי\u0004 קרבנות \u0003שחוטין\u0004 שנדחו מהקרבה, \u0003דלכולי עלמא\u0004 \u0005[שלדעת הכל]\u0006 \u0003נידחין\u0004 הם (גם לדעת מי שסבור שבעלי חיים אינם נדחים),"]]};
